window.AtlasChapters=(window.AtlasChapters||[]).concat([{"id":41,"title":"41단계 — 동명사 동사-ing","html":"\u003ch1 id=\"lesson-title\" data-id=\"41\">41단계 — 동명사 \u003ccode>동사-ing\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003ccode>동사 + -ing\u003c/code>가 \u003cstrong>명사처럼 사용되는 구조\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>동명사 = 동사-ing를 ‘~하는 것 / ~하기’라는 명사처럼 사용\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 형태\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>동사원형 + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>eat → eating\u003c/li>\n\u003cli>read → reading\u003c/li>\n\u003cli>swim → swimming\u003c/li>\n\u003cli>study → studying\u003c/li>\n\u003cli>work → working\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>reading\u003c/strong>.\u003cbr>나는 \u003cstrong>독서하는 것을\u003c/strong> 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>reading\u003c/code>은 실제로 지금 읽고 있다는 뜻이 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>읽는 것 / 독서하기\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 \u003cstrong>명사 역할\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 현재진행형의 \u003ccode>-ing\u003c/code>와 다르다\u003c/h2>\n\u003cp>이미 배운 현재진행형:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am reading\u003c/strong> a book.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 지금 책을 읽고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>reading\u003c/code>은 \u003cstrong>진행 중인 행동\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003cp>동명사:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Reading\u003c/strong> is fun.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>독서는 재미있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>Reading\u003c/code>은 \u003cstrong>“읽는 것”이라는 하나의 개념\u003c/strong>이다.\u003c/p>\n\u003cp>즉 같은 \u003ccode>-ing\u003c/code>라도 역할이 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 동명사가 주어가 될 수 있다\u003c/h2>\n\u003cp>명사처럼 사용하므로 문장의 \u003cstrong>주어\u003c/strong>가 될 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Swimming\u003c/strong> is fun.\u003cbr>수영하는 것은 재미있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>문장 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Swimming / is / fun\u003c/strong>\u003cbr>주어 / 동사 / 보어\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Swimming\u003c/code> 전체가 주어다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">예\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Reading books\u003c/strong> is interesting.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>책을 읽는 것은 재미있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>reading books\u003c/code> 전체가 주어\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. 목적어가 될 수도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>I enjoy \u003cstrong>reading\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>enjoy = 동사\u003c/li>\n\u003cli>reading = 목적어\u003c/li>\n\u003c/ul>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 독서를 즐긴다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사 + 동명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">5. 어떤 동사 뒤에는 동명사를 쓴다\u003c/h2>\n\u003cp>대표적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>enjoy + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I enjoy \u003cstrong>cooking\u003c/strong>.\u003cbr>나는 요리하는 것을 즐긴다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>enjoy\u003c/code> 뒤에는 보통 \u003ccode>to부정사\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I enjoy to cook.\u003cbr>✅ I enjoy cooking.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">자주 쓰는 동사\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>표현\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>enjoy doing\u003c/td>\n\u003ctd>~하는 것을 즐기다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>finish doing\u003c/td>\n\u003ctd>~하는 것을 끝내다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>avoid doing\u003c/td>\n\u003ctd>~하는 것을 피하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>keep doing\u003c/td>\n\u003ctd>계속 ~하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>practice doing\u003c/td>\n\u003ctd>~하는 것을 연습하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>mind doing\u003c/td>\n\u003ctd>~하는 것을 꺼리다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">finish doing\u003c/h3>\n\u003cblockquote>\n\u003cp>I finished \u003cstrong>cleaning\u003c/strong> the room.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 방 청소를 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">avoid doing\u003c/h3>\n\u003cblockquote>\n\u003cp>I avoid \u003cstrong>eating\u003c/strong> late at night.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 밤늦게 먹는 것을 피한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">keep doing\u003c/h3>\n\u003cblockquote>\n\u003cp>She kept \u003cstrong>talking\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 계속 이야기했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>keep + -ing\u003c/code>는 함께 자주 움직이는 중요한 구조다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>keep doing = 계속 ~하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">6. 전치사 뒤에는 동명사\u003c/h2>\n\u003cp>이것이 매우 중요하다.\u003c/p>\n\u003cp>전치사 뒤에 동작을 넣고 싶으면 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>전치사 + 동명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>before \u003cstrong>going\u003c/strong> to bed\u003cbr>잠자리에 들기 전에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>after \u003cstrong>eating\u003c/strong> dinner\u003cbr>저녁을 먹은 후에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>without \u003cstrong>saying\u003c/strong> anything\u003cbr>아무 말도 하지 않고\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">왜?\u003c/h2>\n\u003cp>전치사 뒤에는 기본적으로 \u003cstrong>명사 계열\u003c/strong>이 와야 한다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>after dinner\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>dinner\u003c/code> = 명사\u003c/p>\n\u003cp>그런데 “먹은 후”처럼 동작을 넣고 싶으면 \u003ccode>eat\u003c/code>을 명사처럼 만들어:\u003c/p>\n\u003cblockquote>\n\u003cp>after \u003cstrong>eating\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라고 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. \u003ccode>to\u003c/code>가 있어도 동명사가 오는 경우가 있다\u003c/h2>\n\u003cp>여기가 중요하다.\u003c/p>\n\u003cp>앞에서:\u003c/p>\n\u003cblockquote>\n\u003cp>to + 동사원형 = to부정사\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 배웠다.\u003c/p>\n\u003cp>하지만 \u003cstrong>모든 \u003ccode>to\u003c/code>가 to부정사의 \u003ccode>to\u003c/code>는 아니다.\u003c/strong>\u003c/p>\n\u003cp>전치사 \u003ccode>to\u003c/code>도 있다.\u003c/p>\n\u003cp>전치사 \u003ccode>to\u003c/code> 뒤에서 동작을 말하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to + 동명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 될 수 있다.\u003c/p>\n\u003cp>대표적인 표현:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>look forward to + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하기를 기대하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I look forward to \u003cstrong>seeing\u003c/strong> you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너를 만나기를 기대해.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ look forward to see\u003cbr>✅ look forward to seeing\u003c/p>\n\u003c/blockquote>\n\u003cp>왜냐하면 여기의 \u003ccode>to\u003c/code>는 \u003cstrong>전치사\u003c/strong>이기 때문이다.\u003c/p>\n\u003cp>이 표현은 통째로 익혀두면 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. \u003ccode>be used to + -ing\u003c/code>\u003c/h2>\n\u003cp>또 하나 자주 쓰는 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be used to + 명사 / -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~에 익숙하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m used to \u003cstrong>getting up early\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 일찍 일어나는 것에 익숙하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서도 \u003ccode>to\u003c/code>는 전치사다.\u003c/p>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I&#39;m used to get up early.\u003cbr>✅ I&#39;m used to getting up early.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. \u003ccode>to부정사\u003c/code>와 동명사는 둘 다 “~하는 것”처럼 보인다\u003c/h2>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>to travel\u003c/strong>.\u003cbr>나는 여행하고 싶다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I enjoy \u003cstrong>traveling\u003c/strong>.\u003cbr>나는 여행하는 것을 즐긴다.\u003c/p>\n\u003c/blockquote>\n\u003cp>한국어로 보면 비슷하지만 영어에서는 앞의 동사가 어떤 구조를 요구하는지가 중요하다.\u003c/p>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">want\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>want to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">enjoy\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>enjoy + 동명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I want traveling.\u003cbr>✅ I want to travel.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I enjoy to travel.\u003cbr>✅ I enjoy traveling.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. \u003ccode>like\u003c/code>는 둘 다 가능한 경우도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>reading\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>to read\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하다.\u003c/p>\n\u003cp>다만 의미와 뉘앙스에 차이가 생길 때도 있다.\u003c/p>\n\u003cp>이 문제 때문에 영어 학습자가:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>언제 to부정사고 언제 -ing인가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 많이 헷갈린다.\u003c/p>\n\u003cp>이건 다음 단계에서 체계적으로 정리한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">핵심\u003c/h2>\n\u003cp>동명사:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>동사-ing = ~하는 것 / ~하기\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>명사 역할을 한다.\u003c/p>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">주어\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Swimming\u003c/strong> is fun.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">목적어\u003c/h3>\n\u003cblockquote>\n\u003cp>I enjoy \u003cstrong>swimming\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">전치사 뒤\u003c/h3>\n\u003cblockquote>\n\u003cp>after \u003cstrong>swimming\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 함께 익힐 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>enjoy doing\u003c/strong> = ~하는 것을 즐기다\u003cbr>\u003cstrong>finish doing\u003c/strong> = ~하는 것을 끝내다\u003cbr>\u003cstrong>avoid doing\u003c/strong> = ~하는 것을 피하다\u003cbr>\u003cstrong>keep doing\u003c/strong> = 계속 ~하다\u003cbr>\u003cstrong>look forward to doing\u003c/strong> = ~하기를 기대하다\u003cbr>\u003cstrong>be used to doing\u003c/strong> = ~하는 것에 익숙하다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I enjoy \u003cstrong>reading / to read\u003c/strong> books.\u003c/li>\n\u003cli>She finished \u003cstrong>cleaning / to clean\u003c/strong> the room.\u003c/li>\n\u003cli>He left without \u003cstrong>saying / to say\u003c/strong> goodbye.\u003c/li>\n\u003cli>I look forward to \u003cstrong>see / seeing\u003c/strong> you.\u003c/li>\n\u003cli>I&#39;m used to \u003cstrong>getting / get\u003c/strong> up early.\u003c/li>\n\u003cli>\u003cstrong>Swimming / Swim\u003c/strong> is good exercise.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>42단계 — \u003ccode>to부정사 vs 동명사\u003c/code>: 어떤 동사 뒤에 무엇을 쓰는가\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 형태","depth":2},{"id":"reading-2","label":"2. 현재진행형의 -ing와 다르다","depth":2},{"id":"reading-3","label":"3. 동명사가 주어가 될 수 있다","depth":2},{"id":"reading-4","label":"예","depth":3},{"id":"reading-5","label":"4. 목적어가 될 수도 있다","depth":2},{"id":"reading-6","label":"5. 어떤 동사 뒤에는 동명사를 쓴다","depth":2},{"id":"reading-7","label":"자주 쓰는 동사","depth":2},{"id":"reading-8","label":"finish doing","depth":3},{"id":"reading-9","label":"avoid doing","depth":3},{"id":"reading-10","label":"keep doing","depth":3},{"id":"reading-11","label":"6. 전치사 뒤에는 동명사","depth":2},{"id":"reading-12","label":"왜?","depth":2},{"id":"reading-13","label":"7. to가 있어도 동명사가 오는 경우가 있다","depth":2},{"id":"reading-14","label":"8. be used to + -ing","depth":2},{"id":"reading-15","label":"9. to부정사와 동명사는 둘 다 “~하는 것”처럼 보인다","depth":2},{"id":"reading-16","label":"want","depth":3},{"id":"reading-17","label":"enjoy","depth":3},{"id":"reading-18","label":"10. like는 둘 다 가능한 경우도 있다","depth":2},{"id":"reading-19","label":"핵심","depth":2},{"id":"reading-20","label":"주어","depth":3},{"id":"reading-21","label":"목적어","depth":3},{"id":"reading-22","label":"전치사 뒤","depth":3},{"id":"reading-23","label":"연습","depth":2}],"origin":"conversation","characters":4028,"aliases":{"structure":"reading-1","examples":"reading-4","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-5","topic-5":"reading-6","topic-6":"reading-7","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-18"}},{"id":42,"title":"42단계 — to부정사 vs 동명사(-ing)","html":"\u003ch1 id=\"lesson-title\" data-id=\"42\">42단계 — \u003ccode>to부정사\u003c/code> vs \u003ccode>동명사(-ing)\u003c/code>\u003c/h1>\n\u003cp>이번 단계가 중요하다. 한국어로는 둘 다 흔히 \u003cstrong>“~하는 것 / ~하기”\u003c/strong>로 번역되기 때문에 헷갈리지만, 영어에서는 \u003cstrong>앞에 오는 동사가 무엇이냐\u003c/strong>에 따라 형태가 결정된다.\u003c/p>\n\u003cp>먼저 큰 감각부터 잡자.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to + 동사원형\u003c/strong> → 앞으로 할 행동·의도·계획 쪽으로 기울어짐\u003cbr>\u003cstrong>동사-ing\u003c/strong> → 행동 자체·경험·활동 쪽으로 기울어짐\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 이건 \u003cstrong>경향\u003c/strong>이고, 최종적으로는 \u003ccode>want to\u003c/code>, \u003ccode>enjoy -ing\u003c/code>처럼 \u003cstrong>동사와 구조를 한 묶음으로 익혀야 한다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>to부정사\u003c/code>만 주로 받는 동사\u003c/h2>\n\u003cp>대표적인 것부터 익힌다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>동사\u003c/th>\n\u003cth>구조\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>want\u003c/td>\n\u003ctd>want to do\u003c/td>\n\u003ctd>~하고 싶다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>need\u003c/td>\n\u003ctd>need to do\u003c/td>\n\u003ctd>~할 필요가 있다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>hope\u003c/td>\n\u003ctd>hope to do\u003c/td>\n\u003ctd>~하기를 바라다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>plan\u003c/td>\n\u003ctd>plan to do\u003c/td>\n\u003ctd>~할 계획이다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>decide\u003c/td>\n\u003ctd>decide to do\u003c/td>\n\u003ctd>~하기로 결정하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>promise\u003c/td>\n\u003ctd>promise to do\u003c/td>\n\u003ctd>~하기로 약속하다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">예문\u003c/h3>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>to go\u003c/strong> home.\u003cbr>나는 집에 가고 싶다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We plan \u003cstrong>to travel\u003c/strong> next year.\u003cbr>우리는 내년에 여행할 계획이다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She decided \u003cstrong>to study\u003c/strong> English.\u003cbr>그녀는 영어를 공부하기로 결정했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I want going home.\u003cbr>✅ I want to go home.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">2. 동명사만 주로 받는 동사\u003c/h2>\n\u003cp>대표적인 표현:\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>동사\u003c/th>\n\u003cth>구조\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>enjoy\u003c/td>\n\u003ctd>enjoy doing\u003c/td>\n\u003ctd>~하는 것을 즐기다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>finish\u003c/td>\n\u003ctd>finish doing\u003c/td>\n\u003ctd>~하는 것을 끝내다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>avoid\u003c/td>\n\u003ctd>avoid doing\u003c/td>\n\u003ctd>~하는 것을 피하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>keep\u003c/td>\n\u003ctd>keep doing\u003c/td>\n\u003ctd>계속 ~하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>practice\u003c/td>\n\u003ctd>practice doing\u003c/td>\n\u003ctd>~하는 것을 연습하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>mind\u003c/td>\n\u003ctd>mind doing\u003c/td>\n\u003ctd>~하는 것을 꺼리다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">예문\u003c/h3>\n\u003cblockquote>\n\u003cp>I enjoy \u003cstrong>reading\u003c/strong>.\u003cbr>나는 독서를 즐긴다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She finished \u003cstrong>cleaning\u003c/strong> the room.\u003cbr>그녀는 방 청소를 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He avoids \u003cstrong>driving\u003c/strong> at night.\u003cbr>그는 밤에 운전하는 것을 피한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I enjoy to read.\u003cbr>✅ I enjoy reading.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 왜 이런 차이가 생기나?\u003c/h2>\n\u003cp>감각적으로 비교해보자.\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">want\u003c/h3>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>to eat\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>아직 먹지 않았다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>앞으로 먹고 싶은 행동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 바라보고 있다.\u003c/p>\n\u003cp>그래서 \u003ccode>to eat\u003c/code>.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">enjoy\u003c/h3>\n\u003cblockquote>\n\u003cp>I enjoy \u003cstrong>eating\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>eating\u003c/code>이라는 \u003cstrong>활동 자체를 즐긴다.\u003c/strong>\u003c/p>\n\u003cp>그래서 동명사.\u003c/p>\n\u003cp>이런 차이 때문에:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>to\u003c/code> → 앞으로 향하는 느낌\u003cbr>\u003ccode>-ing\u003c/code> → 행동 자체를 바라보는 느낌\u003c/p>\n\u003c/blockquote>\n\u003cp>이 어느 정도 존재한다.\u003c/p>\n\u003cp>하지만 이것만으로 모든 동사를 결정할 수는 없다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. 둘 다 가능한 동사\u003c/h2>\n\u003cp>일부 동사는 둘 다 받을 수 있다.\u003c/p>\n\u003cp>대표적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>like\u003cbr>love\u003cbr>hate\u003cbr>prefer\u003cbr>start\u003cbr>begin\u003cbr>continue\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>reading\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>to read\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 맞다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>like doing\u003c/code> vs \u003ccode>like to do\u003c/code>\u003c/h2>\n\u003cp>둘 다 “~하는 것을 좋아한다”이지만 약간의 차이가 있을 수 있다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">like doing\u003c/h3>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>reading\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>독서라는 \u003cstrong>활동 자체를 좋아한다.\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">like to do\u003c/h3>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>to read before bed\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>자기 전에 책 읽는 것을 \u003cstrong>좋아하거나 습관적으로 선호한다.\u003c/strong>\u003c/p>\n\u003cp>실제 회화에서는 상당히 겹치므로 초급 단계에서는 둘 다 가능하다는 것을 먼저 기억하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. 둘 다 되지만 뜻이 달라지는 동사\u003c/h2>\n\u003cp>여기부터가 핵심이다.\u003c/p>\n\u003cp>대표적인 것:\u003c/p>\n\u003cblockquote>\n\u003cp>remember\u003cbr>forget\u003cbr>stop\u003cbr>try\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>to\u003c/code>와 \u003ccode>-ing\u003c/code>에 따라 뜻이 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. \u003ccode>remember to do\u003c/code> vs \u003ccode>remember doing\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">remember to do\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>~할 것을 기억하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>아직 해야 할 행동을 잊지 않는다는 뜻.\u003c/p>\n\u003cblockquote>\n\u003cp>Remember \u003cstrong>to call\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나한테 전화하는 거 잊지 마.\u003c/p>\n\u003c/blockquote>\n\u003cp>순서:\u003c/p>\n\u003cblockquote>\n\u003cp>기억함 → 전화함\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">remember doing\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>~했던 것을 기억하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 일어난 행동에 대한 기억.\u003c/p>\n\u003cblockquote>\n\u003cp>I remember \u003cstrong>calling\u003c/strong> you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너한테 전화했던 것이 기억나.\u003c/p>\n\u003c/blockquote>\n\u003cp>순서:\u003c/p>\n\u003cblockquote>\n\u003cp>전화함 → 그 일을 기억함\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>Remember \u003cstrong>to lock\u003c/strong> the door.\u003cbr>문 잠그는 것 잊지 마.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I remember \u003cstrong>locking\u003c/strong> the door.\u003cbr>내가 문을 잠갔던 것이 기억나.\u003c/p>\n\u003c/blockquote>\n\u003cp>완전히 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">8. \u003ccode>forget to do\u003c/code> vs \u003ccode>forget doing\u003c/code>\u003c/h2>\n\u003cp>같은 원리다.\u003c/p>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">forget to do\u003c/h3>\n\u003cblockquote>\n\u003cp>해야 할 일을 잊어서 \u003cstrong>하지 못함\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I forgot \u003cstrong>to call\u003c/strong> her.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀에게 전화하는 것을 깜빡했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 보통 \u003cstrong>전화하지 않았다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">forget doing\u003c/h3>\n\u003cblockquote>\n\u003cp>이미 한 행동에 대한 \u003cstrong>기억이 없음\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ll never forget \u003cstrong>meeting\u003c/strong> her.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀를 처음 만났던 일을 절대 잊지 않을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">9. \u003ccode>stop doing\u003c/code> vs \u003ccode>stop to do\u003c/code>\u003c/h2>\n\u003cp>이건 특히 중요하다.\u003c/p>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">stop doing\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>하던 행동을 그만두다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I stopped \u003cstrong>smoking\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 담배를 끊었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>smoking\u003c/code>이라는 행동 자체를 중단했다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">stop to do\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>다른 것을 하다가 멈추고, ~하기 시작하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I stopped \u003cstrong>to drink some water\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 물을 좀 마시려고 하던 일을 멈췄다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>하던 일 → 멈춤 → 물 마심\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>stop\u003c/code>의 목적이 \u003ccode>to drink\u003c/code>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>He stopped \u003cstrong>talking\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 말하는 것을 멈췄다.\u003c/p>\n\u003c/blockquote>\n\u003cp>vs.\u003c/p>\n\u003cblockquote>\n\u003cp>He stopped \u003cstrong>to talk\u003c/strong> to me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 나와 이야기하려고 가던 길을 멈췄다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">10. \u003ccode>try to do\u003c/code> vs \u003ccode>try doing\u003c/code>\u003c/h2>\n\u003cp>이것도 매우 자주 나온다.\u003c/p>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">try to do\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하려고 노력하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>성공 여부는 모른다.\u003c/p>\n\u003cblockquote>\n\u003cp>I tried \u003cstrong>to open\u003c/strong> the door.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 문을 열려고 노력했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>문이 안 열렸을 수도 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">try doing\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>시험 삼아 ~해보다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>어떤 방법을 시도해보는 느낌이다.\u003c/p>\n\u003cblockquote>\n\u003cp>Try \u003cstrong>opening\u003c/strong> the window.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>창문을 한번 열어봐.\u003c/p>\n\u003c/blockquote>\n\u003cp>예를 들어 방이 더울 때:\u003c/p>\n\u003cblockquote>\n\u003cp>“창문 열어보는 건 어때?”\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-27\" data-reading-anchor=\"reading-27\">11. 한눈에 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>구조\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>remember to do\u003c/td>\n\u003ctd>할 것을 기억하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>remember doing\u003c/td>\n\u003ctd>했던 것을 기억하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>forget to do\u003c/td>\n\u003ctd>할 것을 잊다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>forget doing\u003c/td>\n\u003ctd>했던 일을 잊다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>stop doing\u003c/td>\n\u003ctd>하던 것을 그만두다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>stop to do\u003c/td>\n\u003ctd>~하려고 하던 일을 멈추다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>try to do\u003c/td>\n\u003ctd>~하려고 노력하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>try doing\u003c/td>\n\u003ctd>시험 삼아 ~해보다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">12. 전치사 뒤에서는 다시 \u003ccode>-ing\u003c/code>\u003c/h2>\n\u003cp>이전 단계와 연결한다.\u003c/p>\n\u003cblockquote>\n\u003cp>after \u003cstrong>eating\u003c/strong>\u003cbr>before \u003cstrong>going\u003c/strong>\u003cbr>without \u003cstrong>saying\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>look forward \u003cstrong>to seeing\u003c/strong> you\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>to\u003c/code>는 \u003cstrong>전치사\u003c/strong>이므로 \u003ccode>seeing\u003c/code>.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>want \u003cstrong>to see\u003c/strong> you\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>to\u003c/code>는 \u003cstrong>to부정사\u003c/strong>이므로 \u003ccode>see\u003c/code>.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">13. 가장 좋은 학습법\u003c/h2>\n\u003cp>단어를 이렇게 외우면 안 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>enjoy = 즐기다\u003c/p>\n\u003c/blockquote>\n\u003cp>대신:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>enjoy doing = ~하는 것을 즐기다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 구조까지 함께 외운다.\u003c/p>\n\u003cp>마찬가지로:\u003c/p>\n\u003cblockquote>\n\u003cp>want \u003cstrong>to do\u003c/strong>\u003cbr>decide \u003cstrong>to do\u003c/strong>\u003cbr>avoid \u003cstrong>doing\u003c/strong>\u003cbr>finish \u003cstrong>doing\u003c/strong>\u003cbr>keep \u003cstrong>doing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이렇게 \u003cstrong>동사 + 뒤 구조\u003c/strong>를 하나의 어휘처럼 익히는 게 가장 안정적이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-30\" data-reading-anchor=\"reading-30\">핵심\u003c/h2>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">\u003ccode>to부정사\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>want \u003cstrong>to go\u003c/strong>\u003cbr>plan \u003cstrong>to go\u003c/strong>\u003cbr>decide \u003cstrong>to go\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-32\" data-reading-anchor=\"reading-32\">동명사\u003c/h3>\n\u003cblockquote>\n\u003cp>enjoy \u003cstrong>going\u003c/strong>\u003cbr>avoid \u003cstrong>going\u003c/strong>\u003cbr>finish \u003cstrong>doing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-33\" data-reading-anchor=\"reading-33\">둘 다 되지만 뜻이 변함\u003c/h3>\n\u003cblockquote>\n\u003cp>stop \u003cstrong>doing\u003c/strong> ≠ stop \u003cstrong>to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>try \u003cstrong>doing\u003c/strong> ≠ try \u003cstrong>to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>remember \u003cstrong>doing\u003c/strong> ≠ remember \u003cstrong>to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-34\" data-reading-anchor=\"reading-34\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I enjoy \u003cstrong>reading / to read\u003c/strong> novels.\u003c/li>\n\u003cli>I want \u003cstrong>going / to go\u003c/strong> home.\u003c/li>\n\u003cli>She avoided \u003cstrong>talking / to talk\u003c/strong> to him.\u003c/li>\n\u003cli>Remember \u003cstrong>to call / calling\u003c/strong> me tonight.\u003cbr>→ 오늘 밤 전화하는 걸 잊지 마.\u003c/li>\n\u003cli>I remember \u003cstrong>to meet / meeting\u003c/strong> him ten years ago.\u003cbr>→ 10년 전에 그를 만났던 것이 기억난다.\u003c/li>\n\u003cli>He stopped \u003cstrong>smoking / to smoke\u003c/strong>.\u003cbr>→ 그는 담배를 끊었다.\u003c/li>\n\u003cli>Try \u003cstrong>restarting / to restart\u003c/strong> your phone.\u003cbr>→ 해결 방법으로 휴대폰을 한번 재시작해봐.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>43단계 — 동사의 목적어 구조: \u003ccode>want me to go\u003c/code>, \u003ccode>tell him to wait\u003c/code>, \u003ccode>ask her to come\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. to부정사만 주로 받는 동사","depth":2},{"id":"reading-2","label":"예문","depth":3},{"id":"reading-3","label":"2. 동명사만 주로 받는 동사","depth":2},{"id":"reading-4","label":"예문","depth":3},{"id":"reading-5","label":"3. 왜 이런 차이가 생기나?","depth":2},{"id":"reading-6","label":"want","depth":3},{"id":"reading-7","label":"enjoy","depth":3},{"id":"reading-8","label":"4. 둘 다 가능한 동사","depth":2},{"id":"reading-9","label":"5. like doing vs like to do","depth":2},{"id":"reading-10","label":"like doing","depth":3},{"id":"reading-11","label":"like to do","depth":3},{"id":"reading-12","label":"6. 둘 다 되지만 뜻이 달라지는 동사","depth":2},{"id":"reading-13","label":"7. remember to do vs remember doing","depth":2},{"id":"reading-14","label":"remember to do","depth":3},{"id":"reading-15","label":"remember doing","depth":3},{"id":"reading-16","label":"비교","depth":2},{"id":"reading-17","label":"8. forget to do vs forget doing","depth":2},{"id":"reading-18","label":"forget to do","depth":3},{"id":"reading-19","label":"forget doing","depth":3},{"id":"reading-20","label":"9. stop doing vs stop to do","depth":2},{"id":"reading-21","label":"stop doing","depth":3},{"id":"reading-22","label":"stop to do","depth":3},{"id":"reading-23","label":"비교","depth":2},{"id":"reading-24","label":"10. try to do vs try doing","depth":2},{"id":"reading-25","label":"try to do","depth":3},{"id":"reading-26","label":"try doing","depth":3},{"id":"reading-27","label":"11. 한눈에 비교","depth":2},{"id":"reading-28","label":"12. 전치사 뒤에서는 다시 -ing","depth":2},{"id":"reading-29","label":"13. 가장 좋은 학습법","depth":2},{"id":"reading-30","label":"핵심","depth":2},{"id":"reading-31","label":"to부정사","depth":3},{"id":"reading-32","label":"동명사","depth":3},{"id":"reading-33","label":"둘 다 되지만 뜻이 변함","depth":3},{"id":"reading-34","label":"연습","depth":2}],"origin":"conversation","characters":5284,"aliases":{"structure":"concept","examples":"reading-2","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-3","topic-3":"reading-5","topic-4":"reading-8","topic-5":"reading-9","topic-6":"reading-12","topic-7":"reading-13","topic-8":"reading-16","topic-9":"reading-17","topic-10":"reading-20","topic-11":"reading-23","topic-12":"reading-24"}},{"id":43,"title":"43단계 — 목적어 + to부정사","html":"\u003ch1 id=\"lesson-title\" data-id=\"43\">43단계 — \u003ccode>목적어 + to부정사\u003c/code>\u003c/h1>\n\u003cp>이번에는 아주 중요한 구조다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사 + 사람 + to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>누구에게 ~하라고 하다 / 누가 ~하기를 원하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>want + 사람 + to do\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">기본 구조\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>want + 목적어 + to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>you to come\u003c/strong>.\u003cbr>나는 \u003cstrong>네가 오기를 원한다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>문장 구조:\u003c/p>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>want = 동사\u003c/li>\n\u003cli>you = 목적어\u003c/li>\n\u003cli>to come = 목적어가 할 행동\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I want [you to come].\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>you\u003c/code>가 \u003ccode>come\u003c/code>의 행동 주체다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">2. \u003ccode>I want to go\u003c/code>와 비교\u003c/h2>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">내가 가고 싶다\u003c/h3>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>go\u003c/code>의 주체 = \u003ccode>I\u003c/code>\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">네가 가길 원한다\u003c/h3>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>you to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>go\u003c/code>의 주체 = \u003ccode>you\u003c/code>\u003c/p>\n\u003cp>이 차이가 핵심이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">3. 목적격을 써야 한다\u003c/h2>\n\u003cp>사람이 들어가는 자리는 \u003cstrong>목적어 자리\u003c/strong>이므로 목적격을 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>him to come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그가 오기를 원한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I want he to come.\u003cbr>✅ I want him to come.\u003c/p>\n\u003c/blockquote>\n\u003cp>마찬가지:\u003c/p>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>her to stay\u003c/strong>.\u003cbr>I want \u003cstrong>them to wait\u003c/strong>.\u003cbr>She wants \u003cstrong>me to help\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. \u003ccode>tell + 사람 + to do\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>tell + 사람 + to부정사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>누구에게 ~하라고 말하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I told \u003cstrong>him to wait\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그에게 기다리라고 말했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She told \u003cstrong>me to sit down\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 나에게 앉으라고 말했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">중요한 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>❌ I told to him wait.\u003cbr>❌ I told him wait.\u003cbr>✅ I told him \u003cstrong>to wait\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>tell\u003c/code>은 이 구조에서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>tell + 사람 + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 통째로 익히는 것이 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>ask + 사람 + to do\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>ask + 사람 + to부정사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>누구에게 ~해달라고 요청하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I asked \u003cstrong>her to help me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그녀에게 나를 도와달라고 부탁했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He asked \u003cstrong>me to call him\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 나에게 전화해 달라고 부탁했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. \u003ccode>tell\u003c/code>과 \u003ccode>ask\u003c/code> 차이\u003c/h2>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">tell\u003c/h3>\n\u003cblockquote>\n\u003cp>명령·지시\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I told him to leave.\u003cbr>나는 그에게 나가라고 말했다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">ask\u003c/h3>\n\u003cblockquote>\n\u003cp>요청·부탁\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I asked him to leave.\u003cbr>나는 그에게 나가달라고 부탁했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. \u003ccode>want / tell / ask\u003c/code> 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>구조\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>want someone to do\u003c/td>\n\u003ctd>누가 ~하기를 원하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>tell someone to do\u003c/td>\n\u003ctd>누구에게 ~하라고 말하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>ask someone to do\u003c/td>\n\u003ctd>누구에게 ~해달라고 부탁하다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I want her \u003cstrong>to come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I told her \u003cstrong>to come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I asked her \u003cstrong>to come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>to come\u003c/code>은 같지만 앞 동사 때문에 의미가 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. 부정형\u003c/h2>\n\u003cp>사람에게 \u003cstrong>하지 말라고\u003c/strong> 할 수도 있다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>동사 + 사람 + not to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I told him \u003cstrong>not to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그에게 가지 말라고 말했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She asked me \u003cstrong>not to tell anyone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 나에게 아무에게도 말하지 말라고 부탁했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. \u003ccode>want\u003c/code>의 부정도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>I want you \u003cstrong>not to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로 가능하지만 회화에서는 다소 딱딱할 수 있다.\u003c/p>\n\u003cp>보통은:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>don&#39;t want you to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 네가 가는 것을 원하지 않아.\u003c/p>\n\u003c/blockquote>\n\u003cp>가 더 자연스럽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. \u003ccode>help\u003c/code>는 조금 특별하다\u003c/h2>\n\u003cblockquote>\n\u003cp>help + 사람 + 동사원형\u003c/p>\n\u003c/blockquote>\n\u003cp>또는\u003c/p>\n\u003cblockquote>\n\u003cp>help + 사람 + to부정사\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>She helped me \u003cstrong>carry\u003c/strong> the box.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She helped me \u003cstrong>to carry\u003c/strong> the box.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>그녀는 내가 상자를 옮기는 것을 도왔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>일상에서는 \u003ccode>to\u003c/code>를 생략한 형태도 매우 흔하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">핵심\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">내가 하는 행동\u003c/h3>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">다른 사람이 하는 행동\u003c/h3>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>you to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 자주 쓰는 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>want + 사람 + to do\u003c/strong>\u003cbr>\u003cstrong>tell + 사람 + to do\u003c/strong>\u003cbr>\u003cstrong>ask + 사람 + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>목적어는:\u003c/p>\n\u003cblockquote>\n\u003cp>me / you / him / her / us / them\u003c/p>\n\u003c/blockquote>\n\u003cp>을 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I want \u003cstrong>him to come / he to come\u003c/strong>.\u003c/li>\n\u003cli>She told me \u003cstrong>to wait / wait to\u003c/strong>.\u003c/li>\n\u003cli>I asked her \u003cstrong>to help / helping\u003c/strong> me.\u003c/li>\n\u003cli>He told them \u003cstrong>not to go / to not went\u003c/strong>.\u003c/li>\n\u003cli>She wants \u003cstrong>me to call / I to call\u003c/strong> her.\u003c/li>\n\u003cli>I want \u003cstrong>to go / me to go\u003c/strong> home.\u003cbr>→ 내가 집에 가고 싶다.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>44단계 — 사역동사 \u003ccode>make / let / have\u003c/code>: 왜 \u003ccode>to\u003c/code> 없이 동사원형이 오는가\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. want + 사람 + to do","depth":2},{"id":"reading-2","label":"기본 구조","depth":3},{"id":"reading-3","label":"2. I want to go와 비교","depth":2},{"id":"reading-4","label":"내가 가고 싶다","depth":3},{"id":"reading-5","label":"네가 가길 원한다","depth":3},{"id":"reading-6","label":"3. 목적격을 써야 한다","depth":2},{"id":"reading-7","label":"4. tell + 사람 + to do","depth":2},{"id":"reading-8","label":"중요한 구조","depth":2},{"id":"reading-9","label":"5. ask + 사람 + to do","depth":2},{"id":"reading-10","label":"6. tell과 ask 차이","depth":2},{"id":"reading-11","label":"tell","depth":3},{"id":"reading-12","label":"ask","depth":3},{"id":"reading-13","label":"7. want / tell / ask 비교","depth":2},{"id":"reading-14","label":"8. 부정형","depth":2},{"id":"reading-15","label":"9. want의 부정도 가능","depth":2},{"id":"reading-16","label":"10. help는 조금 특별하다","depth":2},{"id":"reading-17","label":"핵심","depth":2},{"id":"reading-18","label":"내가 하는 행동","depth":3},{"id":"reading-19","label":"다른 사람이 하는 행동","depth":3},{"id":"reading-20","label":"연습","depth":2}],"origin":"conversation","characters":2931,"aliases":{"structure":"reading-2","examples":"concept","contrast":"reading-3","topic-1":"reading-1","topic-2":"reading-3","topic-3":"reading-6","topic-4":"reading-7","topic-5":"reading-8","topic-6":"reading-9","topic-7":"reading-10","topic-8":"reading-13","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-16","topic-12":"reading-17"}},{"id":44,"title":"44단계 — 사역동사 make / let / have","html":"\u003ch1 id=\"lesson-title\" data-id=\"44\">44단계 — 사역동사 \u003ccode>make / let / have\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>사람에게 어떤 행동을 하게 만드는 구조\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>make / let / have + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>여기서는 \u003ccode>to\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>make + 사람 + 동사원형\u003c/code>\u003c/h2>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>누구에게 억지로 ~하게 하다 / ~하게 만들다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My boss made me \u003cstrong>work\u003c/strong> late.\u003cbr>상사가 나를 늦게까지 일하게 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cul>\n\u003cli>My boss = 주어\u003c/li>\n\u003cli>made = 동사\u003c/li>\n\u003cli>me = 목적어\u003c/li>\n\u003cli>work = 동사원형\u003c/li>\n\u003c/ul>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ made me to work\u003cbr>✅ made me work\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 왜 \u003ccode>to\u003c/code>가 없나?\u003c/h2>\n\u003cp>앞 단계에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>tell him \u003cstrong>to wait\u003c/strong>\u003cbr>ask her \u003cstrong>to come\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003ccode>to\u003c/code>를 썼다.\u003c/p>\n\u003cp>하지만 \u003ccode>make\u003c/code>는 문법적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>make + 목적어 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 고정 구조를 사용한다.\u003c/p>\n\u003cp>즉 이것도 표현 하나로 묶어서 익히는 게 좋다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>make someone do something\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>let + 사람 + 동사원형\u003c/code>\u003c/h2>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>누구에게 ~하도록 허락하다 / ~하게 두다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Let me \u003cstrong>go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나 가게 해줘.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>My parents let me \u003cstrong>play\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>부모님은 내가 밖에서 놀게 해주셨다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ let me to go\u003cbr>✅ let me go\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>make\u003c/code>와 \u003ccode>let\u003c/code>의 차이\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">make\u003c/h3>\n\u003cblockquote>\n\u003cp>행동하도록 \u003cstrong>강제\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She made me clean the room.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 나에게 방을 청소하게 했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">let\u003c/h3>\n\u003cblockquote>\n\u003cp>행동하도록 \u003cstrong>허락\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She let me leave early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 내가 일찍 가도록 허락했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>make = 시키다\u003c/strong>\u003cbr>\u003cstrong>let = 하게 해주다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>have + 사람 + 동사원형\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>have\u003c/code>도 사람에게 일을 시키는 의미로 사용할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I had him \u003cstrong>check\u003c/strong> the file.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그에게 파일을 확인하게 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>have\u003c/code>가:\u003c/p>\n\u003cblockquote>\n\u003cp>가지고 있다\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>누구에게 일을 맡기다 / 시키다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">\u003ccode>make\u003c/code>보다 강제성이 약한 경우가 많다\u003c/h2>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">make\u003c/h3>\n\u003cblockquote>\n\u003cp>My boss made me work late.\u003c/p>\n\u003c/blockquote>\n\u003cp>상사가 \u003cstrong>억지로\u003c/strong> 야근하게 했다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">have\u003c/h3>\n\u003cblockquote>\n\u003cp>My boss had me check the report.\u003c/p>\n\u003c/blockquote>\n\u003cp>상사가 업무로 보고서를 확인하게 했다.\u003c/p>\n\u003cp>\u003ccode>have\u003c/code>는 업무 지시나 역할 배정처럼 들릴 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">6. 세 구조 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>표현\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>make someone do\u003c/td>\n\u003ctd>억지로 ~하게 하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>let someone do\u003c/td>\n\u003ctd>~하게 허락하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>have someone do\u003c/td>\n\u003ctd>~하도록 시키다/맡기다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>모두:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. 목적격을 쓴다\u003c/h2>\n\u003cp>앞 단계와 똑같다.\u003c/p>\n\u003cblockquote>\n\u003cp>make \u003cstrong>me\u003c/strong> work\u003cbr>let \u003cstrong>him\u003c/strong> go\u003cbr>have \u003cstrong>her\u003c/strong> call me\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ make I work\u003cbr>✅ make me work\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ let he go\u003cbr>✅ let him go\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. 부정은 어떻게 하나?\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">make\u003c/h3>\n\u003cblockquote>\n\u003cp>Don&#39;t make me \u003cstrong>wait\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나 기다리게 하지 마.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">let\u003c/h3>\n\u003cblockquote>\n\u003cp>Don&#39;t let him \u003cstrong>go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그를 가게 두지 마.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">have\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ll have him \u003cstrong>not use\u003c/strong> this machine.\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로 가능하지만, \u003ccode>have\u003c/code>의 부정 지시는 보통 다른 표현으로 바꾸는 편이 더 자연스럽다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ll tell him not to use this machine.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. \u003ccode>Let me + 동사\u003c/code>는 회화에서 매우 자주 쓴다\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">Let me see.\u003c/h3>\n\u003cblockquote>\n\u003cp>어디 보자.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">Let me check.\u003c/h3>\n\u003cblockquote>\n\u003cp>내가 확인해볼게.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">Let me think.\u003c/h3>\n\u003cblockquote>\n\u003cp>생각 좀 해볼게.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">Let me know.\u003c/h3>\n\u003cblockquote>\n\u003cp>알려줘.\u003c/p>\n\u003c/blockquote>\n\u003cp>특히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>let me know = 나에게 알려줘\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 통째로 외워도 되는 고빈도 표현이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">10. \u003ccode>make + 형용사\u003c/code>도 있다\u003c/h2>\n\u003cp>\u003ccode>make\u003c/code>는 사람에게 행동을 시키는 것뿐 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~을 어떤 상태로 만들다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 구조도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>You make me \u003cstrong>happy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너는 나를 행복하게 해.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>happy\u003c/code>가 동사가 아니라 형용사다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>make + 목적어 + 형용사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>make me \u003cstrong>work\u003c/strong>\u003cbr>나를 일하게 하다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>make me \u003cstrong>happy\u003c/strong>\u003cbr>나를 행복하게 하다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">11. 수동태에서는 \u003ccode>make\u003c/code> 뒤에 \u003ccode>to\u003c/code>가 생긴다\u003c/h2>\n\u003cp>이건 조금 특이하다.\u003c/p>\n\u003cp>능동:\u003c/p>\n\u003cblockquote>\n\u003cp>My boss made me \u003cstrong>work\u003c/strong> late.\u003c/p>\n\u003c/blockquote>\n\u003cp>수동:\u003c/p>\n\u003cblockquote>\n\u003cp>I was made \u003cstrong>to work\u003c/strong> late.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 늦게까지 일하도록 강요받았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>make + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이지만 수동태가 되면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be made to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 된다.\u003c/p>\n\u003cp>지금은 예외로 기억해두면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">핵심\u003c/h2>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">make\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>make + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She made me \u003cstrong>wait\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">let\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>let + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Let me \u003cstrong>go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">have\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I had him \u003cstrong>check\u003c/strong> it.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ make me to go\u003cbr>✅ make me go\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ let me to go\u003cbr>✅ let me go\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>She made me \u003cstrong>wait / to wait\u003c/strong>.\u003c/li>\n\u003cli>Let him \u003cstrong>go / to go\u003c/strong>.\u003c/li>\n\u003cli>I had him \u003cstrong>check / to check\u003c/strong> the file.\u003c/li>\n\u003cli>My parents let me \u003cstrong>play / to play\u003c/strong> outside.\u003c/li>\n\u003cli>You make me \u003cstrong>happy / happily\u003c/strong>.\u003c/li>\n\u003cli>I was made \u003cstrong>work / to work\u003c/strong> late.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>45단계 — 지각동사 \u003ccode>see / hear / watch + 사람 + 동사원형/-ing\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. make + 사람 + 동사원형","depth":2},{"id":"reading-2","label":"2. 왜 to가 없나?","depth":2},{"id":"reading-3","label":"3. let + 사람 + 동사원형","depth":2},{"id":"reading-4","label":"4. make와 let의 차이","depth":2},{"id":"reading-5","label":"make","depth":3},{"id":"reading-6","label":"let","depth":3},{"id":"reading-7","label":"5. have + 사람 + 동사원형","depth":2},{"id":"reading-8","label":"make보다 강제성이 약한 경우가 많다","depth":2},{"id":"reading-9","label":"make","depth":3},{"id":"reading-10","label":"have","depth":3},{"id":"reading-11","label":"6. 세 구조 비교","depth":2},{"id":"reading-12","label":"7. 목적격을 쓴다","depth":2},{"id":"reading-13","label":"8. 부정은 어떻게 하나?","depth":2},{"id":"reading-14","label":"make","depth":3},{"id":"reading-15","label":"let","depth":3},{"id":"reading-16","label":"have","depth":3},{"id":"reading-17","label":"9. Let me + 동사는 회화에서 매우 자주 쓴다","depth":2},{"id":"reading-18","label":"Let me see.","depth":3},{"id":"reading-19","label":"Let me check.","depth":3},{"id":"reading-20","label":"Let me think.","depth":3},{"id":"reading-21","label":"Let me know.","depth":3},{"id":"reading-22","label":"10. make + 형용사도 있다","depth":2},{"id":"reading-23","label":"11. 수동태에서는 make 뒤에 to가 생긴다","depth":2},{"id":"reading-24","label":"핵심","depth":2},{"id":"reading-25","label":"make","depth":3},{"id":"reading-26","label":"let","depth":3},{"id":"reading-27","label":"have","depth":3},{"id":"reading-28","label":"연습","depth":2}],"origin":"conversation","characters":3326,"aliases":{"structure":"reading-11","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-17","topic-11":"reading-22","topic-12":"reading-23"}},{"id":45,"title":"45단계 — 지각동사 see / hear / watch + 사람 + 동사원형 / -ing","html":"\u003ch1 id=\"lesson-title\" data-id=\"45\">45단계 — 지각동사 \u003ccode>see / hear / watch + 사람 + 동사원형 / -ing\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>누군가가 어떤 행동을 하는 것을 보거나 듣는 구조\u003c/strong>다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지각동사 + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>또는\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지각동사 + 사람 + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하지만 의미가 조금 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 지각동사\u003c/h2>\n\u003cp>대표적으로:\u003c/p>\n\u003cul>\n\u003cli>see = 보다\u003c/li>\n\u003cli>hear = 듣다\u003c/li>\n\u003cli>watch = 지켜보다\u003c/li>\n\u003cli>feel = 느끼다\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>cross\u003c/strong> the street.\u003cbr>나는 그가 길을 건너는 것을 봤다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I heard her \u003cstrong>sing\u003c/strong>.\u003cbr>나는 그녀가 노래하는 것을 들었다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>동사원형\u003c/code>이 오는 경우\u003c/h2>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>see/hear/watch + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그 행동 전체를 봄 / 들음\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>open\u003c/strong> the door.\u003c/p>\n\u003c/blockquote>\n\u003cp>나는 그가 문을 여는 것을 봤다.\u003c/p>\n\u003cp>느낌은:\u003c/p>\n\u003cblockquote>\n\u003cp>문을 열기 시작해서 여는 행동이 끝나는 것까지 본 느낌\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>-ing\u003c/code>가 오는 경우\u003c/h2>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>see/hear/watch + 사람 + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그 행동이 진행 중인 장면을 봄 / 들음\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>opening\u003c/strong> the door.\u003c/p>\n\u003c/blockquote>\n\u003cp>나는 그가 문을 열고 있는 모습을 봤다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>그 행동이 진행 중인 순간을 본 느낌\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 비교\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">동사원형\u003c/h3>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>cross\u003c/strong> the street.\u003c/p>\n\u003c/blockquote>\n\u003cp>그가 길을 건너는 \u003cstrong>행동 전체\u003c/strong>를 봤다.\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">-ing\u003c/h3>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>crossing\u003c/strong> the street.\u003c/p>\n\u003c/blockquote>\n\u003cp>그가 길을 \u003cstrong>건너고 있는 장면\u003c/strong>을 봤다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>hear\u003c/code>도 똑같다\u003c/h2>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">전체 행동\u003c/h3>\n\u003cblockquote>\n\u003cp>I heard her \u003cstrong>sing\u003c/strong> a song.\u003c/p>\n\u003c/blockquote>\n\u003cp>그녀가 노래 한 곡 부르는 것을 들었다.\u003c/p>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">진행 중\u003c/h3>\n\u003cblockquote>\n\u003cp>I heard her \u003cstrong>singing\u003c/strong> in the room.\u003c/p>\n\u003c/blockquote>\n\u003cp>방에서 그녀가 노래하고 있는 소리를 들었다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. \u003ccode>watch\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>I watched the children \u003cstrong>play\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>아이들이 노는 것을 지켜봤다.\u003c/p>\n\u003cblockquote>\n\u003cp>I watched the children \u003cstrong>playing\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>아이들이 밖에서 놀고 있는 모습을 지켜봤다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. 목적격을 쓴다\u003c/h2>\n\u003cp>사람은 목적어 자리이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>me / him / her / us / them\u003c/p>\n\u003c/blockquote>\n\u003cp>을 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I saw \u003cstrong>him\u003c/strong> run.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She heard \u003cstrong>me\u003c/strong> call her.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I saw he run.\u003cbr>✅ I saw him run.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. \u003ccode>to\u003c/code>를 쓰지 않는다\u003c/h2>\n\u003cp>능동 구조에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I saw him to run.\u003cbr>✅ I saw him run.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I heard her to sing.\u003cbr>✅ I heard her sing.\u003c/p>\n\u003c/blockquote>\n\u003cp>사역동사와 비슷하게:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지각동사 + 목적어 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조를 사용한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. 사역동사와 비교\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">사역동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I made him \u003cstrong>work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>나는 그에게 일을 시켰다.\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">지각동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>나는 그가 일하는 것을 봤다.\u003c/p>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>목적어 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이지만 의미가 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. 수동태에서는 \u003ccode>to\u003c/code>가 생긴다\u003c/h2>\n\u003cp>능동:\u003c/p>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>enter\u003c/strong> the building.\u003c/p>\n\u003c/blockquote>\n\u003cp>수동:\u003c/p>\n\u003cblockquote>\n\u003cp>He was seen \u003cstrong>to enter\u003c/strong> the building.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>see + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이지만 수동태에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be seen to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 된다.\u003c/p>\n\u003cp>\u003ccode>make\u003c/code>와 비슷한 변화다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">핵심\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">행동 전체\u003c/h3>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>run\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">진행 중인 장면\u003c/h3>\n\u003cblockquote>\n\u003cp>I saw him \u003cstrong>running\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ see him to run\u003cbr>✅ see him run\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I saw him \u003cstrong>cross / to cross\u003c/strong> the street.\u003c/li>\n\u003cli>I saw him \u003cstrong>crossing / to crossing\u003c/strong> the street.\u003c/li>\n\u003cli>She heard me \u003cstrong>call / to call\u003c/strong> her.\u003c/li>\n\u003cli>We watched the children \u003cstrong>play / to play\u003c/strong> outside.\u003c/li>\n\u003cli>I heard her \u003cstrong>singing / to singing\u003c/strong> in the shower.\u003c/li>\n\u003cli>He was seen \u003cstrong>enter / to enter\u003c/strong> the building.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>46단계 — 접속사 \u003ccode>and / but / or / so / because\u003c/code>로 문장 연결하기\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 지각동사","depth":2},{"id":"reading-2","label":"2. 동사원형이 오는 경우","depth":2},{"id":"reading-3","label":"3. -ing가 오는 경우","depth":2},{"id":"reading-4","label":"4. 비교","depth":2},{"id":"reading-5","label":"동사원형","depth":3},{"id":"reading-6","label":"-ing","depth":3},{"id":"reading-7","label":"5. hear도 똑같다","depth":2},{"id":"reading-8","label":"전체 행동","depth":3},{"id":"reading-9","label":"진행 중","depth":3},{"id":"reading-10","label":"6. watch","depth":2},{"id":"reading-11","label":"7. 목적격을 쓴다","depth":2},{"id":"reading-12","label":"8. to를 쓰지 않는다","depth":2},{"id":"reading-13","label":"9. 사역동사와 비교","depth":2},{"id":"reading-14","label":"사역동사","depth":3},{"id":"reading-15","label":"지각동사","depth":3},{"id":"reading-16","label":"10. 수동태에서는 to가 생긴다","depth":2},{"id":"reading-17","label":"핵심","depth":2},{"id":"reading-18","label":"행동 전체","depth":3},{"id":"reading-19","label":"진행 중인 장면","depth":3},{"id":"reading-20","label":"연습","depth":2}],"origin":"conversation","characters":2470,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-20"}},{"id":46,"title":"46단계 — 접속사 and / but / or / so / because","html":"\u003ch1 id=\"lesson-title\" data-id=\"46\">46단계 — 접속사 \u003ccode>and / but / or / so / because\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>문장과 문장을 연결하는 기본 접속사\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심은 이 다섯 개다.\u003c/p>\n\u003cul>\n\u003cli>and = 그리고\u003c/li>\n\u003cli>but = 하지만\u003c/li>\n\u003cli>or = 또는\u003c/li>\n\u003cli>so = 그래서\u003c/li>\n\u003cli>because = 왜냐하면 / ~때문에\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>and\u003c/code>\u003c/h2>\n\u003cp>비슷한 내용을 이어 붙인다.\u003c/p>\n\u003cblockquote>\n\u003cp>I went home, \u003cstrong>and\u003c/strong> I took a shower.\u003cbr>나는 집에 갔고 샤워를 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>문장 + and + 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>또는 단어끼리도 연결할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>coffee \u003cstrong>and\u003c/strong> tea\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>but\u003c/code>\u003c/h2>\n\u003cp>앞내용과 반대되거나 대비되는 내용을 연결한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I was tired, \u003cstrong>but\u003c/strong> I worked.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 피곤했지만 일했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>She is young, \u003cstrong>but\u003c/strong> she is very experienced.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>or\u003c/code>\u003c/h2>\n\u003cp>선택지를 연결한다.\u003c/p>\n\u003cblockquote>\n\u003cp>Do you want coffee \u003cstrong>or\u003c/strong> tea?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>커피 아니면 차 마실래?\u003c/p>\n\u003c/blockquote>\n\u003cp>문장도 연결할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>Hurry up, \u003cstrong>or\u003c/strong> you will be late.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>서둘러, 아니면 늦을 거야.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>so\u003c/code>\u003c/h2>\n\u003cp>앞문장이 \u003cstrong>원인\u003c/strong>, 뒷문장이 \u003cstrong>결과\u003c/strong>다.\u003c/p>\n\u003cblockquote>\n\u003cp>I was tired, \u003cstrong>so\u003c/strong> I went home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 피곤했다. 그래서 집에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>원인 + so + 결과\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>because\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>because\u003c/code>는 이유를 설명한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I went home \u003cstrong>because I was tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 피곤했기 때문에 집에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>결과 + because + 원인\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. \u003ccode>so\u003c/code>와 \u003ccode>because\u003c/code> 비교\u003c/h2>\n\u003cp>둘은 같은 상황을 다른 방향으로 연결한다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">so\u003c/h3>\n\u003cblockquote>\n\u003cp>I was tired, \u003cstrong>so\u003c/strong> I went home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>피곤했다 → 그래서 집에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">because\u003c/h3>\n\u003cblockquote>\n\u003cp>I went home \u003cstrong>because\u003c/strong> I was tired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>집에 갔다 → 왜? 피곤했기 때문에\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>원인 + so + 결과\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>결과 + because + 원인\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>because\u003c/code> 뒤에는 문장이 온다\u003c/h2>\n\u003cblockquote>\n\u003cp>because \u003cstrong>I was tired\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기에는:\u003c/p>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>was = 동사\u003c/li>\n\u003c/ul>\n\u003cp>가 있다.\u003c/p>\n\u003cp>즉 \u003ccode>because\u003c/code> 뒤에는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>형태의 절이 온다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. \u003ccode>because of\u003c/code>와 차이\u003c/h2>\n\u003cp>이건 중요하다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">because + 문장\u003c/h3>\n\u003cblockquote>\n\u003cp>I stayed home \u003cstrong>because it was raining\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">because of + 명사\u003c/h3>\n\u003cblockquote>\n\u003cp>I stayed home \u003cstrong>because of the rain\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>because + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>because of + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. \u003ccode>and\u003c/code>로 동사 두 개 연결\u003c/h2>\n\u003cp>주어가 같으면 반복하지 않아도 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>I went home and \u003cstrong>ate dinner\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>원래는:\u003c/p>\n\u003cblockquote>\n\u003cp>I went home, and I ate dinner.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">10. \u003ccode>but\u003c/code>도 동일\u003c/h2>\n\u003cblockquote>\n\u003cp>She is tired but \u003cstrong>happy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 형용사끼리 연결한다.\u003c/p>\n\u003cblockquote>\n\u003cp>tired + but + happy\u003c/p>\n\u003c/blockquote>\n\u003cp>접속사는 반드시 완전한 문장만 연결하는 건 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">핵심\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">추가\u003c/h3>\n\u003cblockquote>\n\u003cp>and\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">반대\u003c/h3>\n\u003cblockquote>\n\u003cp>but\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">선택\u003c/h3>\n\u003cblockquote>\n\u003cp>or\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">결과\u003c/h3>\n\u003cblockquote>\n\u003cp>so\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">이유\u003c/h3>\n\u003cblockquote>\n\u003cp>because\u003c/p>\n\u003c/blockquote>\n\u003cp>특히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>원인 + so + 결과\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>결과 + because + 원인\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">연습\u003c/h2>\n\u003cp>맞는 접속사를 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I was tired, ___ I went home.\u003cbr>→ so / because\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I went home ___ I was tired.\u003cbr>→ so / because\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She is tired, ___ she is still working.\u003cbr>→ and / but\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Do you want coffee ___ tea?\u003cbr>→ or / so\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I stayed home ___ the rain.\u003cbr>→ because / because of\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I stayed home ___ it was raining.\u003cbr>→ because / because of\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>47단계 — 종속접속사 \u003ccode>when / before / after / while\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. and","depth":2},{"id":"reading-2","label":"2. but","depth":2},{"id":"reading-3","label":"3. or","depth":2},{"id":"reading-4","label":"4. so","depth":2},{"id":"reading-5","label":"5. because","depth":2},{"id":"reading-6","label":"6. so와 because 비교","depth":2},{"id":"reading-7","label":"so","depth":3},{"id":"reading-8","label":"because","depth":3},{"id":"reading-9","label":"7. because 뒤에는 문장이 온다","depth":2},{"id":"reading-10","label":"8. because of와 차이","depth":2},{"id":"reading-11","label":"because + 문장","depth":3},{"id":"reading-12","label":"because of + 명사","depth":3},{"id":"reading-13","label":"9. and로 동사 두 개 연결","depth":2},{"id":"reading-14","label":"10. but도 동일","depth":2},{"id":"reading-15","label":"핵심","depth":2},{"id":"reading-16","label":"추가","depth":3},{"id":"reading-17","label":"반대","depth":3},{"id":"reading-18","label":"선택","depth":3},{"id":"reading-19","label":"결과","depth":3},{"id":"reading-20","label":"이유","depth":3},{"id":"reading-21","label":"연습","depth":2}],"origin":"conversation","characters":2312,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-6","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-21"}},{"id":47,"title":"47단계 — 종속접속사 when / before / after / while","html":"\u003ch1 id=\"lesson-title\" data-id=\"47\">47단계 — 종속접속사 \u003ccode>when / before / after / while\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>시간 관계를 연결하는 접속사\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cul>\n\u003cli>when = ~할 때\u003c/li>\n\u003cli>before = ~하기 전에\u003c/li>\n\u003cli>after = ~한 후에\u003c/li>\n\u003cli>while = ~하는 동안\u003c/li>\n\u003c/ul>\n\u003cp>이 네 개는 뒤에 \u003cstrong>주어 + 동사\u003c/strong>가 올 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>when\u003c/code> — ~할 때\u003c/h2>\n\u003cblockquote>\n\u003cp>I called her \u003cstrong>when I got home\u003c/strong>.\u003cbr>나는 집에 도착했을 때 그녀에게 전화했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주절 + when + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cul>\n\u003cli>I called her = 주절\u003c/li>\n\u003cli>when I got home = 시간절\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 순서를 바꿀 수도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>When I got home,\u003c/strong> I called her.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은 같다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>I called her when I got home.\u003c/p>\n\u003c/blockquote>\n\u003cp>=\u003c/p>\n\u003cblockquote>\n\u003cp>When I got home, I called her.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞에 시간절이 오면 보통 쉼표를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>before\u003c/code> — ~하기 전에\u003c/h2>\n\u003cblockquote>\n\u003cp>I brush my teeth \u003cstrong>before I go to bed\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 자기 전에 이를 닦는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>before + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">순서 반대\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Before I go to bed,\u003c/strong> I brush my teeth.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. \u003ccode>after\u003c/code> — ~한 후에\u003c/h2>\n\u003cblockquote>\n\u003cp>I drink coffee \u003cstrong>after I eat lunch\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 점심을 먹은 후 커피를 마신다.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>After I eat lunch,\u003c/strong> I drink coffee.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">5. \u003ccode>while\u003c/code> — ~하는 동안\u003c/h2>\n\u003cp>\u003ccode>while\u003c/code>은 \u003cstrong>어떤 행동이 진행되는 동안 다른 일이 동시에 일어나는 것\u003c/strong>을 나타낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>I listened to music \u003cstrong>while I was working\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 일하는 동안 음악을 들었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>was working = 진행 중인 행동\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서 \u003ccode>while\u003c/code>은 진행형과 자주 어울린다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">6. \u003ccode>when\u003c/code>과 \u003ccode>while\u003c/code> 차이\u003c/h2>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">when\u003c/h3>\n\u003cp>특정 순간이나 사건\u003c/p>\n\u003cblockquote>\n\u003cp>I was sleeping \u003cstrong>when you called me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네가 전화했을 때 나는 자고 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>called\u003c/code>는 하나의 사건.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">while\u003c/h3>\n\u003cp>어떤 행동이 계속 진행되는 시간\u003c/p>\n\u003cblockquote>\n\u003cp>I listened to music \u003cstrong>while I was working\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일하고 있는 동안 음악을 들었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>when = ~했을 때\u003c/strong>\u003cbr>\u003cstrong>while = ~하고 있는 동안\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. \u003ccode>before / after + 문장\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">문장\u003c/h3>\n\u003cblockquote>\n\u003cp>before \u003cstrong>I go to work\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>go = 동사\u003c/li>\n\u003c/ul>\n\u003cblockquote>\n\u003cp>after \u003cstrong>she finished work\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>she = 주어\u003c/li>\n\u003cli>finished = 동사\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. \u003ccode>before / after + -ing\u003c/code>도 가능하다\u003c/h2>\n\u003cp>앞에서 동명사를 배웠다.\u003c/p>\n\u003cblockquote>\n\u003cp>before \u003cstrong>going to bed\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>자기 전에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>after \u003cstrong>eating dinner\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>저녁을 먹은 후에\u003c/p>\n\u003c/blockquote>\n\u003cp>왜 \u003ccode>-ing\u003c/code>일까?\u003c/p>\n\u003cp>\u003ccode>before / after\u003c/code>가 여기서는 전치사처럼 쓰이고, 뒤에 \u003cstrong>명사 역할의 동명사\u003c/strong>가 오기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">비교\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">접속사\u003c/h3>\n\u003cblockquote>\n\u003cp>before \u003cstrong>I go to bed\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>주어 + 동사\u003c/code>\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">전치사\u003c/h3>\n\u003cblockquote>\n\u003cp>before \u003cstrong>going to bed\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>동명사\u003c/code>\u003c/p>\n\u003cp>둘 다 가능하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">9. 주어가 같을 때 \u003ccode>-ing\u003c/code> 형태가 편하다\u003c/h2>\n\u003cblockquote>\n\u003cp>I wash my face before I go to bed.\u003c/p>\n\u003c/blockquote>\n\u003cp>주어가 둘 다 \u003ccode>I\u003c/code>.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>I wash my face before \u003cstrong>going to bed\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 줄일 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">10. 미래를 말할 때 중요한 규칙\u003c/h2>\n\u003cp>아주 중요하다.\u003c/p>\n\u003cp>\u003ccode>when / before / after\u003c/code> 뒤에서 미래를 말하더라도 보통 \u003ccode>will\u003c/code>을 쓰지 않는다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I&#39;ll call you \u003cstrong>when I get home\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I&#39;ll call you \u003cstrong>when I will get home\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은:\u003c/p>\n\u003cblockquote>\n\u003cp>집에 도착하면 전화할게.\u003c/p>\n\u003c/blockquote>\n\u003cp>미래 이야기인데도 \u003ccode>when\u003c/code> 절에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>get\u003c/p>\n\u003c/blockquote>\n\u003cp>현재형을 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">11. \u003ccode>before / after\u003c/code>도 같다\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;ll eat \u003cstrong>after I finish work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일이 끝난 후 먹을게.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ after I will finish work\u003c/p>\n\u003c/blockquote>\n\u003cp>보통 쓰지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">12. 왜 현재형을 쓰나?\u003c/h2>\n\u003cp>\u003ccode>when / before / after\u003c/code> 같은 시간접속사가 이미:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>앞으로 어떤 시점에\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 미래 관계를 나타내기 때문이다.\u003c/p>\n\u003cp>그래서 시간절에서는 현재형을 사용한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">핵심\u003c/h2>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">when\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>when + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Call me when you arrive.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">before\u003c/h3>\n\u003cblockquote>\n\u003cp>Wash your hands before you eat.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">after\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ll rest after I finish work.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">while\u003c/h3>\n\u003cblockquote>\n\u003cp>I listened to music while I was working.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 미래에서도:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ when I get home\u003cbr>❌ when I will get home\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I&#39;ll call you when I \u003cstrong>get / will get\u003c/strong> home.\u003c/li>\n\u003cli>I brush my teeth \u003cstrong>before / after\u003c/strong> I go to bed.\u003cbr>→ 자기 전에\u003c/li>\n\u003cli>I drank coffee \u003cstrong>after / while\u003c/strong> I ate lunch.\u003cbr>→ 점심 먹은 후에\u003c/li>\n\u003cli>I listened to music \u003cstrong>while / before\u003c/strong> I was working.\u003cbr>→ 일하는 동안\u003c/li>\n\u003cli>She was sleeping \u003cstrong>when / after\u003c/strong> I called her.\u003cbr>→ 내가 전화한 바로 그 시점에\u003c/li>\n\u003cli>I wash my hands before \u003cstrong>eat / eating\u003c/strong> dinner.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>48단계 — 조건문 기초 \u003ccode>if\u003c/code>: “만약 ~하면”\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. when — ~할 때","depth":2},{"id":"reading-2","label":"2. 순서를 바꿀 수도 있다","depth":2},{"id":"reading-3","label":"3. before — ~하기 전에","depth":2},{"id":"reading-4","label":"순서 반대","depth":3},{"id":"reading-5","label":"4. after — ~한 후에","depth":2},{"id":"reading-6","label":"5. while — ~하는 동안","depth":2},{"id":"reading-7","label":"6. when과 while 차이","depth":2},{"id":"reading-8","label":"when","depth":3},{"id":"reading-9","label":"while","depth":3},{"id":"reading-10","label":"7. before / after + 문장","depth":2},{"id":"reading-11","label":"문장","depth":3},{"id":"reading-12","label":"8. before / after + -ing도 가능하다","depth":2},{"id":"reading-13","label":"비교","depth":2},{"id":"reading-14","label":"접속사","depth":3},{"id":"reading-15","label":"전치사","depth":3},{"id":"reading-16","label":"9. 주어가 같을 때 -ing 형태가 편하다","depth":2},{"id":"reading-17","label":"10. 미래를 말할 때 중요한 규칙","depth":2},{"id":"reading-18","label":"11. before / after도 같다","depth":2},{"id":"reading-19","label":"12. 왜 현재형을 쓰나?","depth":2},{"id":"reading-20","label":"핵심","depth":2},{"id":"reading-21","label":"when","depth":3},{"id":"reading-22","label":"before","depth":3},{"id":"reading-23","label":"after","depth":3},{"id":"reading-24","label":"while","depth":3},{"id":"reading-25","label":"연습","depth":2}],"origin":"conversation","characters":3185,"aliases":{"structure":"reading-16","examples":"concept","contrast":"reading-7","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-5","topic-5":"reading-6","topic-6":"reading-7","topic-7":"reading-10","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-18"}},{"id":48,"title":"48단계 — 조건문 기초 if","html":"\u003ch1 id=\"lesson-title\" data-id=\"48\">48단계 — 조건문 기초 \u003ccode>if\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“만약 ~하면”\u003c/strong>을 말하는 가장 기본적인 조건문을 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>if + 조건, 결과\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 주어 + 동사, 주어 + will + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If it rains, I will stay home.\u003c/strong>\u003cbr>비가 오면 나는 집에 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cul>\n\u003cli>If it rains = 조건\u003c/li>\n\u003cli>I will stay home = 결과\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 순서를 바꿀 수도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>If it rains, I will stay home.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>I will stay home if it rains.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 같은 뜻이다.\u003c/p>\n\u003cp>앞에 \u003ccode>if절\u003c/code>이 오면 보통 쉼표를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 미래 이야기인데 \u003ccode>if\u003c/code> 뒤에는 \u003ccode>will\u003c/code>을 쓰지 않는다\u003c/h2>\n\u003cp>이게 가장 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ If it \u003cstrong>rains\u003c/strong>, I will stay home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ If it \u003cstrong>will rain\u003c/strong>, I will stay home.\u003c/p>\n\u003c/blockquote>\n\u003cp>왜냐하면 \u003ccode>if\u003c/code> 자체가 이미:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>앞으로 이런 일이 일어난다면\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 미래 조건을 나타내기 때문이다.\u003c/p>\n\u003cp>그래서 \u003ccode>if절\u003c/code>에서는 보통 \u003cstrong>현재형\u003c/strong>을 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 앞에서 배운 \u003ccode>when\u003c/code>과 같은 원리\u003c/h2>\n\u003cp>이전 단계에서:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ll call you \u003cstrong>when I get home\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 했다.\u003c/p>\n\u003cp>\u003ccode>if\u003c/code>도 비슷하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ll call you \u003cstrong>if I get home early\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 미래이지만:\u003c/p>\n\u003cblockquote>\n\u003cp>when I \u003cstrong>get\u003c/strong>\u003cbr>if I \u003cstrong>get\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 현재형을 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>if\u003c/code>와 \u003ccode>when\u003c/code> 차이\u003c/h2>\n\u003cp>둘 다 한국어로 “~하면”이 될 수 있지만 의미가 다르다.\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">when\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>일어날 것으로 생각함\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>When I get home, I&#39;ll call you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>집에 도착하면 전화할게.\u003c/p>\n\u003c/blockquote>\n\u003cp>집에 도착하는 것은 예정된 일이다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">if\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>일어날지 확실하지 않음\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If I get home early, I&#39;ll call you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>집에 일찍 도착하면 전화할게.\u003c/p>\n\u003c/blockquote>\n\u003cp>일찍 도착할지는 모른다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>when = 언제 일어날지는 몰라도 일어난다고 봄\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>if = 일어날지 자체가 불확실\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 일반적인 사실에도 \u003ccode>if\u003c/code>\u003c/h2>\n\u003cp>항상 \u003ccode>will\u003c/code>이 필요한 것은 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>If you heat ice, it melts.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>얼음을 가열하면 녹는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이건 미래 계획이 아니라 \u003cstrong>일반적인 사실\u003c/strong>이다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 현재형, 현재형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 미래 가능성\u003c/h2>\n\u003cp>가장 먼저 익힐 조건문은 이것이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 현재형, will + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If I have time, I will help you.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>시간이 있으면 도와줄게.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If she comes, we will eat together.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 오면 같이 먹을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If you study, you will improve.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>공부하면 실력이 늘 거야.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. \u003ccode>will\u003c/code> 대신 다른 조동사도 가능\u003c/h2>\n\u003cp>결과 부분에는 상황에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>can\u003cbr>should\u003cbr>must\u003c/p>\n\u003c/blockquote>\n\u003cp>등도 쓸 수 있다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">can\u003c/h3>\n\u003cblockquote>\n\u003cp>If you finish early, you \u003cstrong>can go\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일찍 끝내면 집에 가도 돼.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">should\u003c/h3>\n\u003cblockquote>\n\u003cp>If you feel tired, you \u003cstrong>should rest\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>피곤하면 쉬는 게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">must\u003c/h3>\n\u003cblockquote>\n\u003cp>If you enter this area, you \u003cstrong>must wear\u003c/strong> a helmet.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 구역에 들어가면 반드시 헬멧을 써야 한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. 명령문도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>If you&#39;re tired, \u003cstrong>go home\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>피곤하면 집에 가.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If you see him, \u003cstrong>call me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그를 보면 나한테 전화해.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. \u003ccode>unless\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>unless\u003c/code>는 자주 쓰이는 조건 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>unless = if ... not\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하지 않으면\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I won&#39;t go \u003cstrong>unless you come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>네가 오지 않으면 나도 안 갈 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 의미로:\u003c/p>\n\u003cblockquote>\n\u003cp>I won&#39;t go \u003cstrong>if you don&#39;t come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">핵심\u003c/h2>\n\u003cp>미래 조건:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>If + 현재형, will + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>If it rains, I will stay home.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ If it will rain\u003cbr>✅ If it rains\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>when = 일어날 것으로 봄\u003c/strong>\u003cbr>\u003cstrong>if = 일어날지 불확실\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>If it \u003cstrong>rains / will rain\u003c/strong>, I&#39;ll stay home.\u003c/li>\n\u003cli>If she \u003cstrong>comes / will come\u003c/strong>, we&#39;ll eat together.\u003c/li>\n\u003cli>I&#39;ll call you if I \u003cstrong>have / will have\u003c/strong> time.\u003c/li>\n\u003cli>If you&#39;re tired, you \u003cstrong>should rest / should to rest\u003c/strong>.\u003c/li>\n\u003cli>\u003cstrong>When / If\u003c/strong> I get home, I&#39;ll take a shower.\u003cbr>→ 집에 도착하는 것은 확실함\u003c/li>\n\u003cli>\u003cstrong>When / If\u003c/strong> I have enough money, I&#39;ll buy it.\u003cbr>→ 돈이 충분할지는 모름\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>49단계 — 현재완료 \u003ccode>have/has + p.p.\u003c/code>의 기본 개념\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. 순서를 바꿀 수도 있다","depth":2},{"id":"reading-3","label":"3. 미래 이야기인데 if 뒤에는 will을 쓰지 않는다","depth":2},{"id":"reading-4","label":"4. 앞에서 배운 when과 같은 원리","depth":2},{"id":"reading-5","label":"5. if와 when 차이","depth":2},{"id":"reading-6","label":"when","depth":3},{"id":"reading-7","label":"if","depth":3},{"id":"reading-8","label":"6. 일반적인 사실에도 if","depth":2},{"id":"reading-9","label":"7. 미래 가능성","depth":2},{"id":"reading-10","label":"8. will 대신 다른 조동사도 가능","depth":2},{"id":"reading-11","label":"can","depth":3},{"id":"reading-12","label":"should","depth":3},{"id":"reading-13","label":"must","depth":3},{"id":"reading-14","label":"9. 명령문도 가능","depth":2},{"id":"reading-15","label":"10. unless","depth":2},{"id":"reading-16","label":"핵심","depth":2},{"id":"reading-17","label":"연습","depth":2}],"origin":"conversation","characters":2812,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-16","topic-12":"reading-17"}},{"id":49,"title":"49단계 — 현재완료 have / has + p.p.","html":"\u003ch1 id=\"lesson-title\" data-id=\"49\">49단계 — 현재완료 \u003ccode>have / has + p.p.\u003c/code>\u003c/h1>\n\u003cp>현재완료는 한국어에 딱 대응되는 시제가 없어서 많이 헷갈린다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거에 시작되거나 일어난 일이 현재와 연결되어 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have / has + 과거분사(p.p.)\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 형태\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">I / You / We / They\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">He / She / It\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>has + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have finished\u003c/strong> my work.\u003cbr>나는 일을 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>has finished\u003c/strong> her work.\u003cbr>그녀는 일을 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 과거분사(p.p.)란?\u003c/h2>\n\u003cp>동사의 세 번째 형태라고 생각하면 된다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>과거형\u003c/th>\n\u003cth>과거분사\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>work\u003c/td>\n\u003ctd>worked\u003c/td>\n\u003ctd>worked\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>play\u003c/td>\n\u003ctd>played\u003c/td>\n\u003ctd>played\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>go\u003c/td>\n\u003ctd>went\u003c/td>\n\u003ctd>gone\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>eat\u003c/td>\n\u003ctd>ate\u003c/td>\n\u003ctd>eaten\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>see\u003c/td>\n\u003ctd>saw\u003c/td>\n\u003ctd>seen\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>do\u003c/td>\n\u003ctd>did\u003c/td>\n\u003ctd>done\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>take\u003c/td>\n\u003ctd>took\u003c/td>\n\u003ctd>taken\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>write\u003c/td>\n\u003ctd>wrote\u003c/td>\n\u003ctd>written\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>규칙동사는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>worked → worked\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 과거형과 과거분사가 같다.\u003c/p>\n\u003cp>불규칙동사는 따로 익혀야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 과거시제와 현재완료의 핵심 차이\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">과거시제\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>lost\u003c/strong> my key yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 어제 열쇠를 잃어버렸다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>yesterday\u003c/code>라는 \u003cstrong>끝난 과거 시점\u003c/strong>의 사건이다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have lost\u003c/strong> my key.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>열쇠를 잃어버렸어.\u003c/p>\n\u003c/blockquote>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그래서 지금 열쇠가 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>과거의 사건이 현재 상황과 연결되어 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. 현재완료의 첫 번째 용법 — 결과\u003c/h2>\n\u003cblockquote>\n\u003cp>I have finished my work.\u003c/p>\n\u003c/blockquote>\n\u003cp>단순히:\u003c/p>\n\u003cblockquote>\n\u003cp>일을 끝냈다\u003c/p>\n\u003c/blockquote>\n\u003cp>가 아니라\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그래서 지금 일이 끝난 상태다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">비교\u003c/h3>\n\u003cblockquote>\n\u003cp>I finished my work at 5.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>5시에 일을 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 과거 사건\u003c/p>\n\u003cblockquote>\n\u003cp>I have finished my work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일을 다 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 지금 완료된 상태가 중요\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">5. 경험\u003c/h2>\n\u003cp>현재완료는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~해본 적이 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 경험도 나타낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have been\u003c/strong> to Japan.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 일본에 가본 적이 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>has seen\u003c/strong> that movie.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 그 영화를 본 적이 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">\u003ccode>ever\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>ever = 지금까지 한 번이라도\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>질문에서 자주 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>Have you \u003cstrong>ever been\u003c/strong> to Japan?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일본에 가본 적 있어?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">\u003ccode>never\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>한 번도 ~한 적 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>never been\u003c/strong> to Africa.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 아프리카에 가본 적이 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>never\u003c/code> 자체가 부정이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I haven&#39;t never been\u003cbr>✅ I have never been\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">6. 계속 — 과거부터 지금까지\u003c/h2>\n\u003cp>현재완료는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거에 시작해서 지금도 계속되는 상태\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 나타낼 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have lived\u003c/strong> here for five years.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 여기서 5년째 살고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>5년 전에 시작했고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금도 살고 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 의미다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">7. \u003ccode>for\u003c/code>와 \u003ccode>since\u003c/code>\u003c/h2>\n\u003cp>현재완료와 매우 자주 함께 쓴다.\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">\u003ccode>for\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>기간\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>for five years\u003cbr>5년 동안\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>for two hours\u003cbr>2시간 동안\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>for a long time\u003cbr>오랫동안\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">\u003ccode>since\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>시작 시점\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>since 2020\u003cbr>2020년부터\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>since Monday\u003cbr>월요일부터\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>since I was a child\u003cbr>내가 어렸을 때부터\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I have lived here \u003cstrong>for five years\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>얼마 동안?\u003c/p>\n\u003cblockquote>\n\u003cp>5년 동안\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cblockquote>\n\u003cp>I have lived here \u003cstrong>since 2021\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>언제부터?\u003c/p>\n\u003cblockquote>\n\u003cp>2021년부터\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">8. 완료 — \u003ccode>just / already / yet\u003c/code>\u003c/h2>\n\u003cp>현재완료와 아주 자주 쓰인다.\u003c/p>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">\u003ccode>just\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>방금\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>just finished\u003c/strong> lunch.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나 방금 점심 먹었어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">\u003ccode>already\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>이미\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>already finished\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 이미 끝냈어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">\u003ccode>yet\u003c/code>\u003c/h3>\n\u003cp>보통 질문·부정문에서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>아직 / 벌써\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">질문\u003c/h3>\n\u003cblockquote>\n\u003cp>Have you finished \u003cstrong>yet\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>벌써 끝냈어? / 다 끝냈어?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>I haven&#39;t finished \u003cstrong>yet\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>아직 안 끝냈어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">9. 부정문\u003c/h2>\n\u003cp>\u003ccode>have / has\u003c/code> 뒤에 \u003ccode>not\u003c/code>.\u003c/p>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">have not\u003c/h3>\n\u003cblockquote>\n\u003cp>haven&#39;t\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">has not\u003c/h3>\n\u003cblockquote>\n\u003cp>hasn&#39;t\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>haven&#39;t eaten\u003c/strong> yet.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 아직 먹지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>hasn&#39;t arrived\u003c/strong> yet.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 아직 도착하지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-27\" data-reading-anchor=\"reading-27\">10. 의문문\u003c/h2>\n\u003cp>\u003ccode>have / has\u003c/code>를 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>You have finished.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Have you finished?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She has arrived.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Has she arrived?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">11. \u003ccode>did\u003c/code>를 쓰지 않는다\u003c/h2>\n\u003cp>현재완료 자체에 \u003ccode>have/has\u003c/code>가 있기 때문이다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Did you have finished?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ Have you finished?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">12. 현재완료와 과거시제의 매우 중요한 규칙\u003c/h2>\n\u003cp>\u003cstrong>끝난 과거 시점\u003c/strong>을 정확히 말하면 보통 현재완료를 쓰지 않는다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>yesterday\u003cbr>last year\u003cbr>two days ago\u003cbr>in 2020\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I have seen him yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ I saw him yesterday.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cp>반면 정확한 과거 시점을 말하지 않고 경험 자체를 말하면:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I have seen that movie.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-30\" data-reading-anchor=\"reading-30\">핵심\u003c/h2>\n\u003cp>현재완료:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have / has + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>대표적인 세 가지 감각:\u003c/p>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">결과\u003c/h3>\n\u003cblockquote>\n\u003cp>I have lost my key.\u003cbr>열쇠를 잃어버려서 지금 없다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-32\" data-reading-anchor=\"reading-32\">경험\u003c/h3>\n\u003cblockquote>\n\u003cp>I have been to Japan.\u003cbr>일본에 가본 적 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-33\" data-reading-anchor=\"reading-33\">계속\u003c/h3>\n\u003cblockquote>\n\u003cp>I have lived here for five years.\u003cbr>5년 전부터 지금까지 살고 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-34\" data-reading-anchor=\"reading-34\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I have \u003cstrong>seen / saw\u003c/strong> that movie before.\u003c/li>\n\u003cli>She has \u003cstrong>went / gone\u003c/strong> home.\u003c/li>\n\u003cli>I \u003cstrong>saw / have seen\u003c/strong> him yesterday.\u003c/li>\n\u003cli>Have you \u003cstrong>ever been / ever went\u003c/strong> to Japan?\u003c/li>\n\u003cli>I have lived here \u003cstrong>for / since\u003c/strong> five years.\u003c/li>\n\u003cli>I have lived here \u003cstrong>for / since\u003c/strong> 2020.\u003c/li>\n\u003cli>She hasn&#39;t arrived \u003cstrong>yet / already\u003c/strong>.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>50단계 — 현재완료 vs 과거시제: \u003ccode>I went\u003c/code>와 \u003ccode>I have been\u003c/code>의 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 형태","depth":2},{"id":"reading-2","label":"I / You / We / They","depth":3},{"id":"reading-3","label":"He / She / It","depth":3},{"id":"reading-4","label":"2. 과거분사(p.p.)란?","depth":2},{"id":"reading-5","label":"3. 과거시제와 현재완료의 핵심 차이","depth":2},{"id":"reading-6","label":"과거시제","depth":3},{"id":"reading-7","label":"현재완료","depth":3},{"id":"reading-8","label":"4. 현재완료의 첫 번째 용법 — 결과","depth":2},{"id":"reading-9","label":"비교","depth":3},{"id":"reading-10","label":"5. 경험","depth":2},{"id":"reading-11","label":"ever","depth":2},{"id":"reading-12","label":"never","depth":2},{"id":"reading-13","label":"6. 계속 — 과거부터 지금까지","depth":2},{"id":"reading-14","label":"7. for와 since","depth":2},{"id":"reading-15","label":"for","depth":3},{"id":"reading-16","label":"since","depth":3},{"id":"reading-17","label":"비교","depth":2},{"id":"reading-18","label":"8. 완료 — just / already / yet","depth":2},{"id":"reading-19","label":"just","depth":3},{"id":"reading-20","label":"already","depth":3},{"id":"reading-21","label":"yet","depth":3},{"id":"reading-22","label":"질문","depth":3},{"id":"reading-23","label":"부정","depth":3},{"id":"reading-24","label":"9. 부정문","depth":2},{"id":"reading-25","label":"have not","depth":3},{"id":"reading-26","label":"has not","depth":3},{"id":"reading-27","label":"10. 의문문","depth":2},{"id":"reading-28","label":"11. did를 쓰지 않는다","depth":2},{"id":"reading-29","label":"12. 현재완료와 과거시제의 매우 중요한 규칙","depth":2},{"id":"reading-30","label":"핵심","depth":2},{"id":"reading-31","label":"결과","depth":3},{"id":"reading-32","label":"경험","depth":3},{"id":"reading-33","label":"계속","depth":3},{"id":"reading-34","label":"연습","depth":2}],"origin":"conversation","characters":3842,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-8","topic-5":"reading-10","topic-6":"reading-11","topic-7":"reading-12","topic-8":"reading-13","topic-9":"reading-14","topic-10":"reading-17","topic-11":"reading-18","topic-12":"reading-24"}},{"id":50,"title":"50단계 — 현재완료 vs 과거시제","html":"\u003ch1 id=\"lesson-title\" data-id=\"50\">50단계 — 현재완료 vs 과거시제\u003c/h1>\n\u003cp>이번에는 많이 헷갈리는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I went\u003c/strong>\u003cbr>\u003cstrong>I have been\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>차이를 정리한다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거시제 = 과거의 특정 사건\u003c/strong>\u003cbr>\u003cstrong>현재완료 = 과거 경험이 현재와 연결됨\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>I went to Japan.\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>나는 일본에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>과거의 \u003cstrong>한 사건\u003c/strong>을 말한다.\u003c/p>\n\u003cp>보통 언제 갔는지 문맥이 있거나 과거 시점이 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I went to Japan \u003cstrong>last year\u003c/strong>.\u003cbr>나는 작년에 일본에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>last year\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 끝난 과거 시점이 있으므로 과거시제를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>I have been to Japan.\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>나는 일본에 가본 적이 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 언제 갔는지가 중요하지 않다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금까지 살아오면서 일본 방문 경험이 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 가장 큰 차이\u003c/h2>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">과거시제\u003c/h3>\n\u003cblockquote>\n\u003cp>I went to Taiwan last month.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지난달에 대만에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문의 초점:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>언제 / 어디서 / 무엇을 했는가\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I have been to Taiwan.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>대만에 가본 적이 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문의 초점:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금까지 그런 경험이 있는가\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 질문으로 비교\u003c/h2>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">과거시제\u003c/h3>\n\u003cblockquote>\n\u003cp>When did you go to Japan?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일본에 언제 갔어?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>when\u003c/code>으로 \u003cstrong>과거 시점\u003c/strong>을 묻는다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>Have you ever been to Japan?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일본에 가본 적 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>언제인지는 묻지 않는다.\u003c/p>\n\u003cp>경험 유무만 묻는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. 자연스러운 대화 흐름\u003c/h2>\n\u003cblockquote>\n\u003cp>Have you ever been to Japan?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Yes, I have.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 구체적인 과거 이야기를 시작하면:\u003c/p>\n\u003cblockquote>\n\u003cp>I went there last year.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">1단계\u003c/h3>\n\u003cp>경험 확인\u003c/p>\n\u003cblockquote>\n\u003cp>Have you ever been to Japan?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">2단계\u003c/h3>\n\u003cp>구체적인 과거 설명\u003c/p>\n\u003cblockquote>\n\u003cp>I went there last year.\u003c/p>\n\u003c/blockquote>\n\u003cp>이렇게 \u003cstrong>현재완료 → 과거시제\u003c/strong>로 자연스럽게 넘어가는 경우가 많다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. \u003ccode>have been to\u003c/code>와 \u003ccode>have gone to\u003c/code>\u003c/h2>\n\u003cp>이 둘은 꼭 구분해야 한다.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">have been to\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>가본 적이 있다 / 갔다가 돌아왔다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She has been to Japan.\u003c/p>\n\u003c/blockquote>\n\u003cp>그녀는 일본에 가본 적이 있다.\u003c/p>\n\u003cp>현재는 보통 일본에 있다는 뜻이 아니다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">have gone to\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>~에 가버렸다 / 지금 그곳에 가 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She has gone to Japan.\u003c/p>\n\u003c/blockquote>\n\u003cp>그녀는 일본에 갔다.\u003c/p>\n\u003cp>의미:\u003c/p>\n\u003cblockquote>\n\u003cp>지금 여기 없고 일본에 가 있는 상태\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">7. 비교\u003c/h2>\n\u003cp>아내가 집에 없고 회사에 갔다면:\u003c/p>\n\u003cblockquote>\n\u003cp>She has gone to work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>아내는 출근했다.\u003cbr>→ 지금 집에 없음\u003c/p>\n\u003c/blockquote>\n\u003cp>퇴근해서 이미 돌아왔다면:\u003c/p>\n\u003cblockquote>\n\u003cp>She has been to work.\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로 가능하지만 일상에서는 보통 다른 방식으로 말한다.\u003c/p>\n\u003cp>\u003ccode>have been to\u003c/code>는 특히 \u003cstrong>방문 경험\u003c/strong>에서 많이 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been to Japan three times.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">8. \u003ccode>been\u003c/code>은 무엇인가?\u003c/h2>\n\u003cp>\u003ccode>be\u003c/code>의 변화다.\u003c/p>\n\u003cblockquote>\n\u003cp>be → was/were → been\u003c/p>\n\u003c/blockquote>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>과거\u003c/th>\n\u003cth>과거분사\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>be\u003c/td>\n\u003ctd>was/were\u003c/td>\n\u003ctd>been\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>go\u003c/td>\n\u003ctd>went\u003c/td>\n\u003ctd>gone\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>have \u003cstrong>been\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>have \u003cstrong>gone\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 현재완료 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. \u003ccode>I&#39;ve been to Japan three times.\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>일본에 세 번 가봤다.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재완료는 경험의 \u003cstrong>횟수\u003c/strong>와 잘 어울린다.\u003c/p>\n\u003cblockquote>\n\u003cp>once = 한 번\u003cbr>twice = 두 번\u003cbr>three times = 세 번\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve seen this movie twice.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 영화를 두 번 봤다.\u003c/p>\n\u003c/blockquote>\n\u003cp>지금까지의 경험 횟수다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. 끝난 과거 시간 표현과 현재완료\u003c/h2>\n\u003cp>다음 표현이 있으면 보통 \u003cstrong>과거시제\u003c/strong>를 쓴다.\u003c/p>\n\u003cul>\n\u003cli>yesterday\u003c/li>\n\u003cli>last week\u003c/li>\n\u003cli>last month\u003c/li>\n\u003cli>last year\u003c/li>\n\u003cli>two days ago\u003c/li>\n\u003cli>in 2024\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I went to Japan last year.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I have been to Japan last year.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">11. 현재까지 이어지는 시간은 현재완료 가능\u003c/h2>\n\u003cp>반면 아직 끝나지 않은 시간 범위라면 현재완료를 쓸 수 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve had three cups of coffee \u003cstrong>today\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>오늘 커피를 세 잔 마셨다.\u003c/p>\n\u003cp>지금도 \u003cstrong>오늘이 끝나지 않았기 때문\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">비교\u003c/h2>\n\u003cp>오늘이 아직 진행 중:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve had three cups of coffee today.\u003c/p>\n\u003c/blockquote>\n\u003cp>어제는 완전히 끝남:\u003c/p>\n\u003cblockquote>\n\u003cp>I had three cups of coffee yesterday.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">12. \u003ccode>this week / this year\u003c/code>\u003c/h2>\n\u003cp>현재 기간이 아직 끝나지 않았다면:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve read five books \u003cstrong>this week\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이번 주에 책을 다섯 권 읽었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이번 주가 아직 진행 중이다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>I read five books \u003cstrong>last week\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>지난주는 끝났다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">13. \u003ccode>How long\u003c/code>과 현재완료\u003c/h2>\n\u003cp>현재까지 계속되는 상태를 묻는다면:\u003c/p>\n\u003cblockquote>\n\u003cp>How long \u003cstrong>have you lived\u003c/strong> here?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기 산 지 얼마나 됐어?\u003c/p>\n\u003c/blockquote>\n\u003cp>대답:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve lived here for five years.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cp>과거에 살았지만 지금은 안 산다면:\u003c/p>\n\u003cblockquote>\n\u003cp>How long \u003cstrong>did you live\u003c/strong> there?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>거기서 얼마나 살았어?\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금도 계속 → 현재완료\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>이미 끝남 → 과거시제\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">핵심 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>상황\u003c/th>\n\u003cth>시제\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>작년에 일본에 갔다\u003c/td>\n\u003ctd>I went to Japan last year.\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>일본에 가본 적 있다\u003c/td>\n\u003ctd>I&#39;ve been to Japan.\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>일본에 세 번 가봤다\u003c/td>\n\u003ctd>I&#39;ve been to Japan three times.\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>그녀는 일본에 가 있다\u003c/td>\n\u003ctd>She&#39;s gone to Japan.\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>어제 그를 봤다\u003c/td>\n\u003ctd>I saw him yesterday.\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>그를 전에 본 적 있다\u003c/td>\n\u003ctd>I&#39;ve seen him before.\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>가장 중요한 감각:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거시제 = 끝난 과거를 본다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>현재완료 = 과거부터 지금까지를 한 덩어리로 본다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I \u003cstrong>went / have been\u003c/strong> to Japan last year.\u003c/li>\n\u003cli>I \u003cstrong>went / have been\u003c/strong> to Japan three times.\u003cbr>→ 지금까지의 방문 경험\u003c/li>\n\u003cli>Have you ever \u003cstrong>been / went\u003c/strong> to Taiwan?\u003c/li>\n\u003cli>She has \u003cstrong>been / gone\u003c/strong> to the store.\u003cbr>→ 지금 가게에 가 있어서 여기 없다.\u003c/li>\n\u003cli>I \u003cstrong>saw / have seen\u003c/strong> that movie yesterday.\u003c/li>\n\u003cli>I \u003cstrong>saw / have seen\u003c/strong> that movie before.\u003cbr>→ 현재까지의 경험을 현재완료로 표현\u003c/li>\n\u003cli>I \u003cstrong>lived / have lived\u003c/strong> here for ten years.\u003cbr>→ 지금도 여기 살고 있다.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>51단계 — 현재완료진행형 \u003ccode>have been + -ing\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. I went to Japan.","depth":2},{"id":"reading-2","label":"2. I have been to Japan.","depth":2},{"id":"reading-3","label":"3. 가장 큰 차이","depth":2},{"id":"reading-4","label":"과거시제","depth":3},{"id":"reading-5","label":"현재완료","depth":3},{"id":"reading-6","label":"4. 질문으로 비교","depth":2},{"id":"reading-7","label":"과거시제","depth":3},{"id":"reading-8","label":"현재완료","depth":3},{"id":"reading-9","label":"5. 자연스러운 대화 흐름","depth":2},{"id":"reading-10","label":"1단계","depth":3},{"id":"reading-11","label":"2단계","depth":3},{"id":"reading-12","label":"6. have been to와 have gone to","depth":2},{"id":"reading-13","label":"have been to","depth":3},{"id":"reading-14","label":"have gone to","depth":3},{"id":"reading-15","label":"7. 비교","depth":2},{"id":"reading-16","label":"8. been은 무엇인가?","depth":2},{"id":"reading-17","label":"9. I've been to Japan three times.","depth":2},{"id":"reading-18","label":"10. 끝난 과거 시간 표현과 현재완료","depth":2},{"id":"reading-19","label":"11. 현재까지 이어지는 시간은 현재완료 가능","depth":2},{"id":"reading-20","label":"비교","depth":2},{"id":"reading-21","label":"12. this week / this year","depth":2},{"id":"reading-22","label":"13. How long과 현재완료","depth":2},{"id":"reading-23","label":"핵심 비교","depth":2},{"id":"reading-24","label":"연습","depth":2}],"origin":"conversation","characters":3830,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-3","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-6","topic-5":"reading-9","topic-6":"reading-12","topic-7":"reading-15","topic-8":"reading-16","topic-9":"reading-17","topic-10":"reading-18","topic-11":"reading-19","topic-12":"reading-20"}},{"id":51,"title":"51단계 — 현재완료진행형 have/has been + -ing","html":"\u003ch1 id=\"lesson-title\" data-id=\"51\">51단계 — 현재완료진행형 \u003ccode>have/has been + -ing\u003c/code>\u003c/h1>\n\u003cp>현재완료진행형은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거에 시작해서 지금까지 계속하고 있는 행동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 말할 때 쓴다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have/has + been + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 형태\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">I / You / We / They\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>have been + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">He / She / It\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>has been + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have been studying\u003c/strong> English.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 영어를 계속 공부해오고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>has been working\u003c/strong> all day.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 하루 종일 계속 일하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 시간 흐름\u003c/h2>\n\u003cp>예를 들어:\u003c/p>\n\u003cblockquote>\n\u003cp>I have been studying English for two hours.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>두 시간 전에 공부 시작\u003cbr>↓\u003cbr>계속 공부\u003cbr>↓\u003cbr>\u003cstrong>지금도 공부 중\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>과거 ───────→ 현재\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 연결이 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 현재진행형과 차이\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">현재진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am studying\u003c/strong> English.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 지금 영어 공부하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>현재 이 순간\u003c/strong>에 초점이 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">현재완료진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have been studying\u003c/strong> English for two hours.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 두 시간째 영어 공부를 하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>언제 시작해서 지금까지 얼마나 계속했는지\u003c/strong>가 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. 현재완료와 비교\u003c/h2>\n\u003cp>이 차이가 중요하다.\u003c/p>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>I have read the book.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그 책을 읽었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>완료·결과\u003c/strong>에 초점.\u003c/p>\n\u003cp>책을 다 읽었다는 의미가 자연스럽다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">현재완료진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>I have been reading the book.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그 책을 계속 읽고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>과정·지속\u003c/strong>에 초점.\u003c/p>\n\u003cp>아직 다 읽지 않았을 수도 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">5. \u003ccode>for\u003c/code>\u003c/h2>\n\u003cp>기간을 말할 때 자주 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>for two hours\u003cbr>두 시간 동안\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>for three days\u003cbr>사흘 동안\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>for a long time\u003cbr>오랫동안\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been waiting \u003cstrong>for an hour\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 한 시간째 기다리고 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. \u003ccode>since\u003c/code>\u003c/h2>\n\u003cp>시작 시점을 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>since 8 a.m.\u003cbr>오전 8시부터\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>since Monday\u003cbr>월요일부터\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>since last year\u003cbr>작년부터\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been working \u003cstrong>since 8 a.m.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 오전 8시부터 계속 일하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. \u003ccode>for\u003c/code>와 \u003ccode>since\u003c/code>\u003c/h2>\n\u003cp>다시 정리하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>for + 기간\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>since + 시작 시점\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been studying for three hours.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ve been studying since 7 o&#39;clock.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. 질문\u003c/h2>\n\u003cp>\u003ccode>have/has\u003c/code>를 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Have you been waiting long?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>오래 기다렸어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>How long have you been studying English?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>영어 공부한 지 얼마나 됐어?\u003c/p>\n\u003c/blockquote>\n\u003cp>이 구조는 실제 회화에서 아주 자주 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. 부정문\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>have/has + not + been + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>haven&#39;t been sleeping\u003c/strong> well.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 요즘 잠을 잘 못 자고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>hasn&#39;t been feeling\u003c/strong> well.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 요즘 몸 상태가 좋지 않다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. 최근까지 계속했던 행동도 가능\u003c/h2>\n\u003cp>반드시 \u003cstrong>지금 이 순간 행동 중\u003c/strong>이어야 하는 것은 아니다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;re wet. Have you been running?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너 젖었네. 뛰고 있었어?\u003c/p>\n\u003c/blockquote>\n\u003cp>지금은 멈췄을 수도 있다.\u003c/p>\n\u003cp>하지만 최근까지 달렸던 행동의 \u003cstrong>결과가 지금 보인다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">11. \u003ccode>recently / lately\u003c/code>\u003c/h2>\n\u003cp>현재완료진행형과 자주 쓰인다.\u003c/p>\n\u003cblockquote>\n\u003cp>recently = 최근에\u003cbr>lately = 요즘\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been feeling tired \u003cstrong>lately\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나 요즘 계속 피곤해.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ve been working a lot \u003cstrong>recently\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>최근에 일을 많이 하고 있어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">12. 모든 동사를 진행형으로 쓰지는 않는다\u003c/h2>\n\u003cp>\u003ccode>know\u003c/code>, \u003ccode>like\u003c/code>, \u003ccode>believe\u003c/code>처럼 \u003cstrong>상태를 나타내는 동사\u003c/strong>는 보통 진행형을 잘 쓰지 않는다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I have known him for ten years.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I have been knowing him for ten years.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>know\u003c/code>는 상태동사이므로 현재완료를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">13. 현재완료 vs 현재완료진행형\u003c/h2>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">결과가 중요\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ve cleaned the room.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>방 청소를 끝냈다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">과정이 중요\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ve been cleaning the room.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>계속 방 청소를 하고 있었다 / 하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve read five books this month.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>5권이라는 결과\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been reading a lot this month.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>계속 많이 읽어온 활동\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">핵심\u003c/h2>\n\u003cp>현재완료진행형:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have/has been + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>의미:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거부터 지금까지 계속 진행된 행동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve been studying English for two hours.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>현재완료 = 결과·완료 쪽\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>현재완료진행형 = 과정·지속 쪽\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I \u003cstrong>have been studying / am studying\u003c/strong> English for three hours.\u003cbr>→ 세 시간째 계속 공부 중\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She \u003cstrong>has been working / has working\u003c/strong> since 8 a.m.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>How long \u003cstrong>have you been waiting / are you waiting\u003c/strong>?\u003cbr>→ 얼마나 오래 기다려왔는지\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>have known / have been knowing\u003c/strong> him for ten years.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;ve \u003cstrong>read / been reading\u003c/strong> five books this month.\u003cbr>→ 다섯 권이라는 결과 강조\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;ve \u003cstrong>read / been reading\u003c/strong> a lot lately.\u003cbr>→ 최근 계속 많이 읽어온 활동\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>52단계 — 수동태 \u003ccode>be + p.p.\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 형태","depth":2},{"id":"reading-2","label":"I / You / We / They","depth":3},{"id":"reading-3","label":"He / She / It","depth":3},{"id":"reading-4","label":"2. 시간 흐름","depth":2},{"id":"reading-5","label":"3. 현재진행형과 차이","depth":2},{"id":"reading-6","label":"현재진행형","depth":3},{"id":"reading-7","label":"현재완료진행형","depth":3},{"id":"reading-8","label":"4. 현재완료와 비교","depth":2},{"id":"reading-9","label":"현재완료","depth":3},{"id":"reading-10","label":"현재완료진행형","depth":3},{"id":"reading-11","label":"5. for","depth":2},{"id":"reading-12","label":"6. since","depth":2},{"id":"reading-13","label":"7. for와 since","depth":2},{"id":"reading-14","label":"8. 질문","depth":2},{"id":"reading-15","label":"9. 부정문","depth":2},{"id":"reading-16","label":"10. 최근까지 계속했던 행동도 가능","depth":2},{"id":"reading-17","label":"11. recently / lately","depth":2},{"id":"reading-18","label":"12. 모든 동사를 진행형으로 쓰지는 않는다","depth":2},{"id":"reading-19","label":"13. 현재완료 vs 현재완료진행형","depth":2},{"id":"reading-20","label":"결과가 중요","depth":3},{"id":"reading-21","label":"과정이 중요","depth":3},{"id":"reading-22","label":"핵심","depth":2},{"id":"reading-23","label":"연습","depth":2}],"origin":"conversation","characters":3400,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-8","topic-5":"reading-11","topic-6":"reading-12","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-18"}},{"id":52,"title":"52단계 — 수동태 be + p.p.","html":"\u003ch1 id=\"lesson-title\" data-id=\"52\">52단계 — 수동태 \u003ccode>be + p.p.\u003c/code>\u003c/h1>\n\u003cp>수동태는 \u003cstrong>누가 행동했는지보다, 행동을 받은 대상이 중요할 때\u003c/strong> 쓴다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 + 과거분사(p.p.)\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 능동태와 수동태\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">능동태\u003c/h3>\n\u003cblockquote>\n\u003cp>Tom built the house.\u003cbr>톰이 그 집을 지었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Tom\u003c/strong> = 행동한 사람\u003cbr>\u003cstrong>built\u003c/strong> = 행동\u003cbr>\u003cstrong>the house\u003c/strong> = 행동을 받은 대상\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">수동태\u003c/h3>\n\u003cblockquote>\n\u003cp>The house \u003cstrong>was built\u003c/strong> by Tom.\u003cbr>그 집은 톰에 의해 지어졌다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 \u003ccode>the house\u003c/code>가 문장의 중심이 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 기본 구조\u003c/h2>\n\u003cp>능동태:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사 + 목적어\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>수동태:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>목적어 → 주어 + be동사 + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She cleaned the room.\u003c/p>\n\u003c/blockquote>\n\u003cp>수동태:\u003c/p>\n\u003cblockquote>\n\u003cp>The room \u003cstrong>was cleaned\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 왜 수동태를 쓰나?\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">① 누가 했는지 모를 때\u003c/h3>\n\u003cblockquote>\n\u003cp>My car \u003cstrong>was stolen\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내 차가 도난당했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>누가 훔쳤는지 모른다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">② 누가 했는지 중요하지 않을 때\u003c/h3>\n\u003cblockquote>\n\u003cp>This building \u003cstrong>was built in 2020\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 건물은 2020년에 지어졌다.\u003c/p>\n\u003c/blockquote>\n\u003cp>건축한 사람이 누구인지보다 \u003cstrong>건물 자체\u003c/strong>가 중요하다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">③ 결과를 강조할 때\u003c/h3>\n\u003cblockquote>\n\u003cp>The work \u003cstrong>is finished\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일이 끝났다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">4. \u003ccode>by + 사람\u003c/code>\u003c/h2>\n\u003cp>행동한 사람을 말하고 싶으면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>by + 행동한 사람\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>The book was written \u003cstrong>by him\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그 책은 그가 썼다.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요:\u003c/p>\n\u003cp>\u003ccode>by\u003c/code>는 전치사이므로 뒤에는 목적격을 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>by me\u003cbr>by him\u003cbr>by her\u003cbr>by them\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ by he\u003cbr>✅ by him\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">5. 현재 수동태\u003c/h2>\n\u003cp>현재시제:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>am / is / are + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>능동:\u003c/p>\n\u003cblockquote>\n\u003cp>People use this room every day.\u003c/p>\n\u003c/blockquote>\n\u003cp>수동:\u003c/p>\n\u003cblockquote>\n\u003cp>This room \u003cstrong>is used\u003c/strong> every day.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>The door \u003cstrong>is locked\u003c/strong> every night.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>The doors \u003cstrong>are locked\u003c/strong> every night.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">6. 과거 수동태\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>was / were + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>능동:\u003c/p>\n\u003cblockquote>\n\u003cp>They built this bridge in 2010.\u003c/p>\n\u003c/blockquote>\n\u003cp>수동:\u003c/p>\n\u003cblockquote>\n\u003cp>This bridge \u003cstrong>was built\u003c/strong> in 2010.\u003c/p>\n\u003c/blockquote>\n\u003cp>복수:\u003c/p>\n\u003cblockquote>\n\u003cp>These buildings \u003cstrong>were built\u003c/strong> in 2010.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">7. 미래 수동태\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>will be + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>The work \u003cstrong>will be finished\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그 일은 내일 끝날 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조를 보면:\u003c/p>\n\u003cblockquote>\n\u003cp>will + be + finished\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>will\u003c/code> 뒤에는 동사원형이므로 \u003ccode>be\u003c/code>.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">8. 조동사 + 수동태\u003c/h2>\n\u003cp>조동사 뒤에서도:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + be + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">can\u003c/h3>\n\u003cblockquote>\n\u003cp>This problem \u003cstrong>can be solved\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 문제는 해결될 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">must\u003c/h3>\n\u003cblockquote>\n\u003cp>This work \u003cstrong>must be finished\u003c/strong> today.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 일은 오늘 반드시 끝나야 한다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">should\u003c/h3>\n\u003cblockquote>\n\u003cp>The door \u003cstrong>should be locked\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>문은 잠겨 있어야 한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">9. 현재완료 수동태\u003c/h2>\n\u003cp>앞에서 현재완료를 배웠다.\u003c/p>\n\u003cp>현재완료:\u003c/p>\n\u003cblockquote>\n\u003cp>have/has + p.p.\u003c/p>\n\u003c/blockquote>\n\u003cp>수동태까지 결합하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>have/has been + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>The work \u003cstrong>has been finished\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그 일이 완료되었다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The building \u003cstrong>has been completed\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그 건물이 완공되었다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">10. 현재완료진행형과 헷갈리지 않기\u003c/h2>\n\u003cp>둘 다 \u003ccode>has been\u003c/code>이 나온다.\u003c/p>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">현재완료진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>has been working\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 계속 일해왔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>has been + \u003cstrong>-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">현재완료 수동태\u003c/h3>\n\u003cblockquote>\n\u003cp>The work \u003cstrong>has been finished\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>일이 완료되었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>has been + \u003cstrong>p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>been + -ing → 진행\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>been + p.p. → 수동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">11. 능동 → 수동 만드는 순서\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom cleaned the room.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">① 목적어 찾기\u003c/h3>\n\u003cblockquote>\n\u003cp>the room\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">② 목적어를 앞으로\u003c/h3>\n\u003cblockquote>\n\u003cp>The room\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">③ 원래 시제 확인\u003c/h3>\n\u003cp>\u003ccode>cleaned\u003c/code> → 과거\u003c/p>\n\u003cp>따라서 \u003ccode>be\u003c/code>도 과거:\u003c/p>\n\u003cblockquote>\n\u003cp>was\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">④ 본동사를 과거분사로\u003c/h3>\n\u003cblockquote>\n\u003cp>clean → cleaned\u003c/p>\n\u003c/blockquote>\n\u003cp>결과:\u003c/p>\n\u003cblockquote>\n\u003cp>The room \u003cstrong>was cleaned\u003c/strong> by Tom.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">12. 불규칙 과거분사 주의\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>과거\u003c/th>\n\u003cth>p.p.\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>write\u003c/td>\n\u003ctd>wrote\u003c/td>\n\u003ctd>written\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>make\u003c/td>\n\u003ctd>made\u003c/td>\n\u003ctd>made\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>build\u003c/td>\n\u003ctd>built\u003c/td>\n\u003ctd>built\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>eat\u003c/td>\n\u003ctd>ate\u003c/td>\n\u003ctd>eaten\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>take\u003c/td>\n\u003ctd>took\u003c/td>\n\u003ctd>taken\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>see\u003c/td>\n\u003ctd>saw\u003c/td>\n\u003ctd>seen\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>do\u003c/td>\n\u003ctd>did\u003c/td>\n\u003ctd>done\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>break\u003c/td>\n\u003ctd>broke\u003c/td>\n\u003ctd>broken\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Shakespeare wrote this play.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>This play was \u003cstrong>written\u003c/strong> by Shakespeare.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>wrote\u003c/code>가 아니라 \u003ccode>written\u003c/code>.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">13. 수동태가 안 되는 동사도 있다\u003c/h2>\n\u003cp>수동태는 기본적으로 \u003cstrong>목적어가 있는 동사\u003c/strong>에서 만든다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom opened the door.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>the door\u003c/code>라는 목적어가 있으므로:\u003c/p>\n\u003cblockquote>\n\u003cp>The door was opened.\u003c/p>\n\u003c/blockquote>\n\u003cp>가능하다.\u003c/p>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom slept.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>sleep\u003c/code>에는 목적어가 없다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Tom was slept.\u003c/p>\n\u003c/blockquote>\n\u003cp>이런 수동태를 만들 수 없다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-30\" data-reading-anchor=\"reading-30\">14. \u003ccode>be made to\u003c/code> 다시 연결\u003c/h2>\n\u003cp>앞에서 배운 사역동사:\u003c/p>\n\u003ch3 id=\"reading-31\" data-reading-anchor=\"reading-31\">능동\u003c/h3>\n\u003cblockquote>\n\u003cp>My boss made me \u003cstrong>work\u003c/strong> late.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>make + 사람 + 동사원형\u003c/code>\u003c/p>\n\u003cp>그런데 수동태에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was made to work\u003c/strong> late.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>to\u003c/code>가 생긴다.\u003c/p>\n\u003cp>이건 예외적으로 꼭 기억한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-32\" data-reading-anchor=\"reading-32\">핵심\u003c/h2>\n\u003cp>수동태:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-33\" data-reading-anchor=\"reading-33\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>is made\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-34\" data-reading-anchor=\"reading-34\">과거\u003c/h3>\n\u003cblockquote>\n\u003cp>was made\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-35\" data-reading-anchor=\"reading-35\">미래\u003c/h3>\n\u003cblockquote>\n\u003cp>will be made\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-36\" data-reading-anchor=\"reading-36\">조동사\u003c/h3>\n\u003cblockquote>\n\u003cp>can be made\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-37\" data-reading-anchor=\"reading-37\">현재완료\u003c/h3>\n\u003cblockquote>\n\u003cp>has been made\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>능동 = 누가 했다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>수동 = 무엇이 당했다 / 처리되었다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-38\" data-reading-anchor=\"reading-38\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>This building \u003cstrong>was built / was build\u003c/strong> in 2020.\u003c/li>\n\u003cli>The room \u003cstrong>is cleaned / is clean\u003c/strong> every day.\u003cbr>→ 매일 청소된다.\u003c/li>\n\u003cli>The work \u003cstrong>will finish / will be finished\u003c/strong> tomorrow.\u003c/li>\n\u003cli>This problem \u003cstrong>can solve / can be solved\u003c/strong>.\u003c/li>\n\u003cli>The book was written \u003cstrong>by he / by him\u003c/strong>.\u003c/li>\n\u003cli>The window has been \u003cstrong>broken / broke\u003c/strong>.\u003c/li>\n\u003cli>My boss made me work late.\u003cbr>→ I was made \u003cstrong>work / to work\u003c/strong> late.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>53단계 — 관계대명사 \u003ccode>who / which / that\u003c/code>: 명사를 뒤에서 설명하는 구조\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 능동태와 수동태","depth":2},{"id":"reading-2","label":"능동태","depth":3},{"id":"reading-3","label":"수동태","depth":3},{"id":"reading-4","label":"2. 기본 구조","depth":2},{"id":"reading-5","label":"3. 왜 수동태를 쓰나?","depth":2},{"id":"reading-6","label":"① 누가 했는지 모를 때","depth":3},{"id":"reading-7","label":"② 누가 했는지 중요하지 않을 때","depth":3},{"id":"reading-8","label":"③ 결과를 강조할 때","depth":3},{"id":"reading-9","label":"4. by + 사람","depth":2},{"id":"reading-10","label":"5. 현재 수동태","depth":2},{"id":"reading-11","label":"단수","depth":3},{"id":"reading-12","label":"복수","depth":3},{"id":"reading-13","label":"6. 과거 수동태","depth":2},{"id":"reading-14","label":"7. 미래 수동태","depth":2},{"id":"reading-15","label":"8. 조동사 + 수동태","depth":2},{"id":"reading-16","label":"can","depth":3},{"id":"reading-17","label":"must","depth":3},{"id":"reading-18","label":"should","depth":3},{"id":"reading-19","label":"9. 현재완료 수동태","depth":2},{"id":"reading-20","label":"10. 현재완료진행형과 헷갈리지 않기","depth":2},{"id":"reading-21","label":"현재완료진행형","depth":3},{"id":"reading-22","label":"현재완료 수동태","depth":3},{"id":"reading-23","label":"11. 능동 → 수동 만드는 순서","depth":2},{"id":"reading-24","label":"① 목적어 찾기","depth":3},{"id":"reading-25","label":"② 목적어를 앞으로","depth":3},{"id":"reading-26","label":"③ 원래 시제 확인","depth":3},{"id":"reading-27","label":"④ 본동사를 과거분사로","depth":3},{"id":"reading-28","label":"12. 불규칙 과거분사 주의","depth":2},{"id":"reading-29","label":"13. 수동태가 안 되는 동사도 있다","depth":2},{"id":"reading-30","label":"14. be made to 다시 연결","depth":2},{"id":"reading-31","label":"능동","depth":3},{"id":"reading-32","label":"핵심","depth":2},{"id":"reading-33","label":"현재","depth":3},{"id":"reading-34","label":"과거","depth":3},{"id":"reading-35","label":"미래","depth":3},{"id":"reading-36","label":"조동사","depth":3},{"id":"reading-37","label":"현재완료","depth":3},{"id":"reading-38","label":"연습","depth":2}],"origin":"conversation","characters":3998,"aliases":{"structure":"reading-4","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-9","topic-5":"reading-10","topic-6":"reading-13","topic-7":"reading-14","topic-8":"reading-15","topic-9":"reading-19","topic-10":"reading-20","topic-11":"reading-23","topic-12":"reading-28"}},{"id":53,"title":"53단계 — 관계대명사 who / which / that","html":"\u003ch1 id=\"lesson-title\" data-id=\"53\">53단계 — 관계대명사 \u003ccode>who / which / that\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>명사를 뒤에서 설명하는 구조\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>명사 + 관계대명사 + 설명\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>The man \u003cstrong>who lives next door\u003c/strong> is a doctor.\u003cbr>옆집에 사는 그 남자는 의사다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>who lives next door\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 앞의 \u003ccode>the man\u003c/code>을 설명한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 관계대명사는 왜 쓰나?\u003c/h2>\n\u003cp>원래 두 문장이 있다고 하자.\u003c/p>\n\u003cblockquote>\n\u003cp>I know a man.\u003cbr>He lives next door.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 문장에 같은 사람:\u003c/p>\n\u003cblockquote>\n\u003cp>a man = he\u003c/p>\n\u003c/blockquote>\n\u003cp>가 반복된다.\u003c/p>\n\u003cp>이를 하나로 합치면:\u003c/p>\n\u003cblockquote>\n\u003cp>I know a man \u003cstrong>who lives next door\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 옆집에 사는 남자를 안다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>who\u003c/code> — 사람\u003c/h2>\n\u003cp>앞의 명사가 \u003cstrong>사람\u003c/strong>일 때 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>The woman \u003cstrong>who works here\u003c/strong> is my friend.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기서 일하는 여자는 내 친구다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>The woman + who works here\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>who\u003c/code>는 앞의 \u003ccode>woman\u003c/code>을 다시 가리킨다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>who = 그 사람이\u003c/p>\n\u003c/blockquote>\n\u003cp>정도로 생각할 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>which\u003c/code> — 사물\u003c/h2>\n\u003cp>앞의 명사가 \u003cstrong>사물\u003c/strong>일 때 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I bought a phone \u003cstrong>which has a good camera\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 카메라가 좋은 휴대폰을 샀다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>which = 그 휴대폰이\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>that\u003c/code> — 사람과 사물 모두 가능\u003c/h2>\n\u003cp>\u003ccode>that\u003c/code>은 제한적 관계절에서 사람이나 사물 모두에 자주 쓸 수 있다.\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">사람\u003c/h3>\n\u003cblockquote>\n\u003cp>The man \u003cstrong>that works here\u003c/strong> is my friend.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">사물\u003c/h3>\n\u003cblockquote>\n\u003cp>The phone \u003cstrong>that I bought\u003c/strong> is expensive.\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서 초반에는:\u003c/p>\n\u003cblockquote>\n\u003cp>사람 → who / that\u003cbr>사물 → which / that\u003c/p>\n\u003c/blockquote>\n\u003cp>으로 기억하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 주격 관계대명사\u003c/h2>\n\u003cp>먼저 관계대명사가 뒤 문장의 \u003cstrong>주어 역할\u003c/strong>을 하는 경우다.\u003c/p>\n\u003cp>원래:\u003c/p>\n\u003cblockquote>\n\u003cp>I know a woman.\u003cbr>\u003cstrong>She\u003c/strong> speaks Japanese.\u003c/p>\n\u003c/blockquote>\n\u003cp>합치면:\u003c/p>\n\u003cblockquote>\n\u003cp>I know a woman \u003cstrong>who speaks Japanese\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>who\u003c/code>가 \u003ccode>speaks\u003c/code>의 주어다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ who she speaks Japanese\u003cbr>✅ who speaks Japanese\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 \u003ccode>who\u003c/code>가 주어 역할을 하고 있기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 사물도 같은 원리\u003c/h2>\n\u003cp>원래:\u003c/p>\n\u003cblockquote>\n\u003cp>I bought a car.\u003cbr>\u003cstrong>It\u003c/strong> is very fast.\u003c/p>\n\u003c/blockquote>\n\u003cp>합치면:\u003c/p>\n\u003cblockquote>\n\u003cp>I bought a car \u003cstrong>which is very fast\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>I bought a car \u003cstrong>that is very fast\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>which/that\u003c/code>이 \u003ccode>is\u003c/code>의 주어다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 목적격 관계대명사\u003c/h2>\n\u003cp>이번에는 관계대명사가 뒤 문장의 \u003cstrong>목적어 역할\u003c/strong>을 하는 경우다.\u003c/p>\n\u003cp>원래:\u003c/p>\n\u003cblockquote>\n\u003cp>I met a man.\u003cbr>You know \u003cstrong>him\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>합치면:\u003c/p>\n\u003cblockquote>\n\u003cp>I met a man \u003cstrong>who you know\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cul>\n\u003cli>you = 주어\u003c/li>\n\u003cli>know = 동사\u003c/li>\n\u003cli>who = 목적어\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>네가 아는 남자\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 목적격에서는 생략 가능\u003c/h2>\n\u003cp>아주 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I met the man \u003cstrong>who you know\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>who\u003c/code>는 목적어이므로 생략할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I met the man \u003cstrong>you know\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 맞다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">사물도 동일\u003c/h2>\n\u003cblockquote>\n\u003cp>This is the book \u003cstrong>that I bought\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>This is the book \u003cstrong>I bought\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>이것은 내가 산 책이다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">9. 주격은 생략하면 안 된다\u003c/h2>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">주격\u003c/h3>\n\u003cblockquote>\n\u003cp>The man \u003cstrong>who lives here\u003c/strong> is my uncle.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>who\u003c/code>를 빼면:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ The man lives here is my uncle.\u003c/p>\n\u003c/blockquote>\n\u003cp>뒤 절의 주어가 사라져서 문장이 무너진다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">목적격\u003c/h3>\n\u003cblockquote>\n\u003cp>The man \u003cstrong>who I met yesterday\u003c/strong> is my uncle.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>I = 주어\u003c/p>\n\u003c/blockquote>\n\u003cp>가 이미 있다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>The man \u003cstrong>I met yesterday\u003c/strong> is my uncle.\u003c/p>\n\u003c/blockquote>\n\u003cp>가능하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. 구분하는 가장 쉬운 방법\u003c/h2>\n\u003cp>관계대명사 뒤를 본다.\u003c/p>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">관계대명사 바로 뒤에 동사가 나오면\u003c/h3>\n\u003cblockquote>\n\u003cp>who \u003cstrong>lives\u003c/strong> here\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>who\u003c/code>가 주어다.\u003c/p>\n\u003cp>→ \u003cstrong>생략 불가\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">관계대명사 뒤에 주어가 따로 나오면\u003c/h3>\n\u003cblockquote>\n\u003cp>who \u003cstrong>I met\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 \u003ccode>I\u003c/code>가 주어다.\u003c/p>\n\u003cp>\u003ccode>who\u003c/code>는 목적어.\u003c/p>\n\u003cp>→ \u003cstrong>생략 가능\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">11. 예문 비교\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">주격\u003c/h3>\n\u003cblockquote>\n\u003cp>The girl \u003cstrong>who is singing\u003c/strong> is my daughter.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>노래하고 있는 여자아이는 내 딸이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>who\u003c/code> = 노래하는 사람\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">목적격\u003c/h3>\n\u003cblockquote>\n\u003cp>The girl \u003cstrong>who I saw yesterday\u003c/strong> is my daughter.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 어제 본 여자아이는 내 딸이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I\u003c/code>가 \u003ccode>saw\u003c/code>의 주어이고 \u003ccode>who\u003c/code>가 목적어.\u003c/p>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>The girl \u003cstrong>I saw yesterday\u003c/strong> is my daughter.\u003c/p>\n\u003c/blockquote>\n\u003cp>도 가능하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">핵심\u003c/h2>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">사람\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>who / that\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">사물\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>which / that\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">주격 관계대명사\u003c/h3>\n\u003cblockquote>\n\u003cp>The man \u003cstrong>who works here\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>who\u003c/code>가 주어 → 생략 불가\u003c/p>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">목적격 관계대명사\u003c/h3>\n\u003cblockquote>\n\u003cp>The man \u003cstrong>who I met\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I\u003c/code>가 주어 → \u003ccode>who\u003c/code> 생략 가능\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>The man \u003cstrong>who works / who he works\u003c/strong> here is my friend.\u003c/li>\n\u003cli>This is the car \u003cstrong>which is / which it is\u003c/strong> very fast.\u003c/li>\n\u003cli>The woman \u003cstrong>who I met / who I met her\u003c/strong> yesterday is a doctor.\u003c/li>\n\u003cli>This is the book \u003cstrong>that I bought / that I bought it\u003c/strong>.\u003c/li>\n\u003cli>The man \u003cstrong>who lives here / lives here\u003c/strong> is my uncle.\u003c/li>\n\u003cli>The book \u003cstrong>that I bought / I bought\u003c/strong> was expensive.\u003cbr>→ 둘 다 가능한지 생각해봐.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>54단계 — 관계사 \u003ccode>whose / where / when\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 관계대명사는 왜 쓰나?","depth":2},{"id":"reading-2","label":"2. who — 사람","depth":2},{"id":"reading-3","label":"3. which — 사물","depth":2},{"id":"reading-4","label":"4. that — 사람과 사물 모두 가능","depth":2},{"id":"reading-5","label":"사람","depth":3},{"id":"reading-6","label":"사물","depth":3},{"id":"reading-7","label":"5. 주격 관계대명사","depth":2},{"id":"reading-8","label":"6. 사물도 같은 원리","depth":2},{"id":"reading-9","label":"7. 목적격 관계대명사","depth":2},{"id":"reading-10","label":"8. 목적격에서는 생략 가능","depth":2},{"id":"reading-11","label":"사물도 동일","depth":2},{"id":"reading-12","label":"9. 주격은 생략하면 안 된다","depth":2},{"id":"reading-13","label":"주격","depth":3},{"id":"reading-14","label":"목적격","depth":3},{"id":"reading-15","label":"10. 구분하는 가장 쉬운 방법","depth":2},{"id":"reading-16","label":"관계대명사 바로 뒤에 동사가 나오면","depth":3},{"id":"reading-17","label":"관계대명사 뒤에 주어가 따로 나오면","depth":3},{"id":"reading-18","label":"11. 예문 비교","depth":2},{"id":"reading-19","label":"주격","depth":3},{"id":"reading-20","label":"목적격","depth":3},{"id":"reading-21","label":"핵심","depth":2},{"id":"reading-22","label":"사람","depth":3},{"id":"reading-23","label":"사물","depth":3},{"id":"reading-24","label":"주격 관계대명사","depth":3},{"id":"reading-25","label":"목적격 관계대명사","depth":3},{"id":"reading-26","label":"연습","depth":2}],"origin":"conversation","characters":3381,"aliases":{"structure":"concept","examples":"reading-18","contrast":"reading-15","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-15","topic-12":"reading-18"}},{"id":54,"title":"54단계 — whose / where / when","html":"\u003ch1 id=\"lesson-title\" data-id=\"54\">54단계 — \u003ccode>whose / where / when\u003c/code>\u003c/h1>\n\u003cp>이번에는 관계절을 조금 확장해서:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>whose\u003c/strong> = 누구의\u003c/li>\n\u003cli>\u003cstrong>where\u003c/strong> = 어디에서\u003c/li>\n\u003cli>\u003cstrong>when\u003c/strong> = 언제\u003c/li>\n\u003c/ul>\n\u003cp>를 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>whose\u003c/code> — 누구의\u003c/h2>\n\u003cp>앞의 사람이 \u003cstrong>무엇을 소유하고 있는지\u003c/strong> 설명할 때 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I know a man \u003cstrong>whose son is a doctor\u003c/strong>.\u003cbr>나는 아들이 의사인 남자를 안다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>whose son = 그 남자의 아들\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 구조\u003c/h2>\n\u003cp>원래 두 문장:\u003c/p>\n\u003cblockquote>\n\u003cp>I know a man.\u003cbr>\u003cstrong>His son\u003c/strong> is a doctor.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>his\u003c/code>가 앞의 \u003ccode>a man\u003c/code>을 가리킨다.\u003c/p>\n\u003cp>합치면:\u003c/p>\n\u003cblockquote>\n\u003cp>I know a man \u003cstrong>whose son is a doctor\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>whose + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 또 다른 예\u003c/h2>\n\u003cblockquote>\n\u003cp>She is the woman \u003cstrong>whose car was stolen\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 차를 도난당한 여자다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>whose car\u003c/code>:\u003c/p>\n\u003cblockquote>\n\u003cp>그녀의 차\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>whose\u003c/code> 뒤에는 명사가 온다\u003c/h2>\n\u003cblockquote>\n\u003cp>whose car\u003cbr>whose daughter\u003cbr>whose phone\u003cbr>whose house\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ the man whose is car expensive\u003cbr>✅ the man whose car is expensive\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>where\u003c/code> — 장소를 설명\u003c/h2>\n\u003cp>장소를 나타내는 명사 뒤에서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그곳에서 / 그곳에\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미로 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This is the restaurant \u003cstrong>where we ate dinner\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기가 우리가 저녁을 먹었던 식당이다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. 원래 문장으로 보면\u003c/h2>\n\u003cblockquote>\n\u003cp>This is the restaurant.\u003cbr>We ate dinner \u003cstrong>there\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>there\u003c/code>가 \u003ccode>the restaurant\u003c/code>을 가리킨다.\u003c/p>\n\u003cp>합치면:\u003c/p>\n\u003cblockquote>\n\u003cp>This is the restaurant \u003cstrong>where we ate dinner\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>where = 그곳에서\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 역할이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. \u003ccode>where\u003c/code> 뒤에는 주어 + 동사\u003c/h2>\n\u003cblockquote>\n\u003cp>the restaurant \u003cstrong>where we ate\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>where = 그곳에서\u003c/li>\n\u003cli>we = 주어\u003c/li>\n\u003cli>ate = 동사\u003c/li>\n\u003c/ul>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ the restaurant where ate dinner\u003cbr>✅ the restaurant where we ate dinner\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">8. \u003ccode>when\u003c/code> — 시간을 설명\u003c/h2>\n\u003cp>시간을 나타내는 명사 뒤에서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그때 / ~했을 때\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미로 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I remember the day \u003cstrong>when we first met\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 우리가 처음 만난 날을 기억한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">9. 원래 문장\u003c/h2>\n\u003cblockquote>\n\u003cp>I remember the day.\u003cbr>We first met \u003cstrong>on that day\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>합치면:\u003c/p>\n\u003cblockquote>\n\u003cp>I remember the day \u003cstrong>when we first met\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>when\u003c/code>이:\u003c/p>\n\u003cblockquote>\n\u003cp>on that day\u003c/p>\n\u003c/blockquote>\n\u003cp>역할을 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">10. \u003ccode>where\u003c/code>와 \u003ccode>which\u003c/code> 차이\u003c/h2>\n\u003cp>이 부분이 중요하다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">where\u003c/h3>\n\u003cblockquote>\n\u003cp>This is the house \u003cstrong>where I live\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기가 내가 사는 집이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>where\u003c/code> 자체에:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그곳에서\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 장소 의미가 들어 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">which\u003c/h3>\n\u003cblockquote>\n\u003cp>This is the house \u003cstrong>which I bought\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기가 내가 산 집이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>which\u003c/code>는 \u003ccode>bought\u003c/code>의 목적어다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>the house \u003cstrong>where I live\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>live\u003c/code> 뒤에 목적어가 필요 없다.\u003c/p>\n\u003cblockquote>\n\u003cp>I live \u003cstrong>there\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cblockquote>\n\u003cp>the house \u003cstrong>which I bought\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>bought\u003c/code>에는 목적어가 필요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I bought \u003cstrong>the house\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">11. \u003ccode>where\u003c/code>를 \u003ccode>in which\u003c/code>로 바꿀 수도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>This is the house \u003cstrong>where I live\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>=\u003c/p>\n\u003cblockquote>\n\u003cp>This is the house \u003cstrong>in which I live\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 맞다.\u003c/p>\n\u003cp>하지만 일상에서는 \u003ccode>where\u003c/code>가 훨씬 간단하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">12. \u003ccode>when\u003c/code>도 비슷하다\u003c/h2>\n\u003cblockquote>\n\u003cp>the day \u003cstrong>when we met\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>=\u003c/p>\n\u003cblockquote>\n\u003cp>the day \u003cstrong>on which we met\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 회화에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>the day when we met\u003c/p>\n\u003c/blockquote>\n\u003cp>이 자연스럽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">13. \u003ccode>when\u003c/code>은 생략되는 경우도 많다\u003c/h2>\n\u003cblockquote>\n\u003cp>I remember the day \u003cstrong>when we met\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>I remember the day \u003cstrong>we met\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">14. \u003ccode>where\u003c/code>도 경우에 따라 다른 구조로 바뀔 수 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>This is the place \u003cstrong>where I work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>자연스럽다.\u003c/p>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>This is the place \u003cstrong>I visited\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>where\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003cp>왜냐하면:\u003c/p>\n\u003cblockquote>\n\u003cp>I visited \u003cstrong>the place\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003ccode>the place\u003c/code>가 \u003ccode>visited\u003c/code>의 목적어이기 때문이다.\u003c/p>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ the place where I work\u003cbr>✅ the place that I visited\u003cbr>✅ the place I visited\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">핵심\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">소유\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>whose + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>the man whose son is a doctor\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">장소\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>where + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>the house where I live\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">시간\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>when + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>the day when we met\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>the house \u003cstrong>where I live\u003c/strong>\u003cbr>내가 사는 집\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>the house \u003cstrong>that I bought\u003c/strong>\u003cbr>내가 산 집\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>where\u003c/code>는 \u003cstrong>장소 관계\u003c/strong>, \u003ccode>that\u003c/code>은 \u003cstrong>목적어 관계\u003c/strong>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I know a woman \u003cstrong>whose daughter / who daughter\u003c/strong> is a doctor.\u003c/li>\n\u003cli>This is the house \u003cstrong>where I live / where I live it\u003c/strong>.\u003c/li>\n\u003cli>I remember the day \u003cstrong>when we met / when we met it\u003c/strong>.\u003c/li>\n\u003cli>This is the car \u003cstrong>where I bought / that I bought\u003c/strong>.\u003c/li>\n\u003cli>This is the office \u003cstrong>where I work / which I work\u003c/strong>.\u003c/li>\n\u003cli>She is the woman \u003cstrong>whose car / who car\u003c/strong> was stolen.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>55단계 — 관계절의 제한적/비제한적 용법과 쉼표 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. whose — 누구의","depth":2},{"id":"reading-2","label":"2. 구조","depth":2},{"id":"reading-3","label":"3. 또 다른 예","depth":2},{"id":"reading-4","label":"4. whose 뒤에는 명사가 온다","depth":2},{"id":"reading-5","label":"5. where — 장소를 설명","depth":2},{"id":"reading-6","label":"6. 원래 문장으로 보면","depth":2},{"id":"reading-7","label":"7. where 뒤에는 주어 + 동사","depth":2},{"id":"reading-8","label":"8. when — 시간을 설명","depth":2},{"id":"reading-9","label":"9. 원래 문장","depth":2},{"id":"reading-10","label":"10. where와 which 차이","depth":2},{"id":"reading-11","label":"where","depth":3},{"id":"reading-12","label":"which","depth":3},{"id":"reading-13","label":"비교","depth":2},{"id":"reading-14","label":"11. where를 in which로 바꿀 수도 있다","depth":2},{"id":"reading-15","label":"12. when도 비슷하다","depth":2},{"id":"reading-16","label":"13. when은 생략되는 경우도 많다","depth":2},{"id":"reading-17","label":"14. where도 경우에 따라 다른 구조로 바뀔 수 있다","depth":2},{"id":"reading-18","label":"핵심","depth":2},{"id":"reading-19","label":"소유","depth":3},{"id":"reading-20","label":"장소","depth":3},{"id":"reading-21","label":"시간","depth":3},{"id":"reading-22","label":"비교","depth":2},{"id":"reading-23","label":"연습","depth":2}],"origin":"conversation","characters":3500,"aliases":{"structure":"reading-2","examples":"reading-3","contrast":"reading-10","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-13","topic-12":"reading-14"}},{"id":55,"title":"55단계 — 관계절의 제한적 / 비제한적 용법","html":"\u003ch1 id=\"lesson-title\" data-id=\"55\">55단계 — 관계절의 제한적 / 비제한적 용법\u003c/h1>\n\u003cp>이번에는 관계대명사에서 \u003cstrong>쉼표가 왜 중요한지\u003c/strong> 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>쉼표 없음 = 어떤 사람/사물인지 구별하는 데 꼭 필요한 정보\u003c/strong>\u003cbr>\u003cstrong>쉼표 있음 = 이미 누구/무엇인지 알고 있고, 추가 설명만 붙임\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 제한적 관계절 — 쉼표 없음\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>The employees \u003cstrong>who work on site\u003c/strong> wear helmets.\u003cbr>현장에서 일하는 직원들은 헬멧을 쓴다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>who work on site\u003c/p>\n\u003c/blockquote>\n\u003cp>는 \u003cstrong>어떤 직원들인지 골라주는 정보\u003c/strong>다.\u003c/p>\n\u003cp>즉 모든 직원이 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>현장에서 일하는 직원들\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>만 말한다.\u003c/p>\n\u003cp>그래서 이 설명을 빼면 의미가 달라진다.\u003c/p>\n\u003cblockquote>\n\u003cp>The employees wear helmets.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 직원들이 헬멧을 쓴다.\u003c/p>\n\u003cp>범위가 완전히 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 비제한적 관계절 — 쉼표 있음\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My father, \u003cstrong>who lives in Busan\u003c/strong>, is retired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리 아버지는 부산에 사시는데, 은퇴하셨다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>My father\u003c/code>만으로 이미 누구인지 특정되어 있다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>who lives in Busan\u003c/p>\n\u003c/blockquote>\n\u003cp>은 그 사람을 구별하기 위한 정보가 아니라 \u003cstrong>추가 정보\u003c/strong>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 두 문장을 비교\u003c/h2>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">쉼표 없음\u003c/h3>\n\u003cblockquote>\n\u003cp>My brother \u003cstrong>who lives in Seoul\u003c/strong> is a doctor.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>서울에 사는 내 형제는 의사다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 표현은 자연스럽게:\u003c/p>\n\u003cblockquote>\n\u003cp>형제가 여러 명인데 그중 \u003cstrong>서울에 사는 형제\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌을 줄 수 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">쉼표 있음\u003c/h3>\n\u003cblockquote>\n\u003cp>My brother, \u003cstrong>who lives in Seoul\u003c/strong>, is a doctor.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>내 형제는 의사인데, 서울에 산다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 \u003ccode>my brother\u003c/code>가 누구인지 알고 있고\u003cbr>서울에 산다는 사실은 추가 설명이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 핵심은 “정보가 중요한가?”가 아니다\u003c/h2>\n\u003cp>이렇게 생각하면 안 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>중요한 정보 → 쉼표 없음\u003cbr>안 중요한 정보 → 쉼표 있음\u003c/p>\n\u003c/blockquote>\n\u003cp>정확한 기준은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>앞의 명사가 누구/무엇인지 특정하는 데 관계절이 필요한가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">예\u003c/h2>\n\u003cblockquote>\n\u003cp>The car \u003cstrong>that is parked outside\u003c/strong> is mine.\u003c/p>\n\u003c/blockquote>\n\u003cp>밖에 차가 여러 대 있을 수 있다.\u003c/p>\n\u003cp>어떤 차인지 알려주기 위해:\u003c/p>\n\u003cblockquote>\n\u003cp>that is parked outside\u003c/p>\n\u003c/blockquote>\n\u003cp>가 필요하다.\u003c/p>\n\u003cp>→ 제한적\u003c/p>\n\u003chr>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>My car, \u003cstrong>which is parked outside\u003c/strong>, is new.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>my car\u003c/code>로 이미 특정되어 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>which is parked outside\u003c/p>\n\u003c/blockquote>\n\u003cp>는 추가 설명.\u003c/p>\n\u003cp>→ 비제한적\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 비제한적 관계절에서는 \u003ccode>that\u003c/code>을 쓰지 않는다\u003c/h2>\n\u003cp>중요하다.\u003c/p>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">제한적\u003c/h3>\n\u003cblockquote>\n\u003cp>The car \u003cstrong>that I bought\u003c/strong> is expensive. ✅\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">비제한적\u003c/h3>\n\u003cblockquote>\n\u003cp>My car, \u003cstrong>which I bought last year\u003c/strong>, is expensive. ✅\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ My car, \u003cstrong>that I bought last year\u003c/strong>, is expensive.\u003c/p>\n\u003c/blockquote>\n\u003cp>비제한적 관계절에서는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>사람 → \u003cstrong>who\u003c/strong>\u003cbr>사물 → \u003cstrong>which\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">6. 비제한적 관계절의 관계대명사는 생략하지 않는다\u003c/h2>\n\u003cp>제한적 목적격 관계대명사는 생략 가능했다.\u003c/p>\n\u003cblockquote>\n\u003cp>The book \u003cstrong>that I bought\u003c/strong> was expensive.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>The book \u003cstrong>I bought\u003c/strong> was expensive.\u003c/p>\n\u003c/blockquote>\n\u003cp>가능하다.\u003c/p>\n\u003chr>\n\u003cp>하지만 비제한적이면:\u003c/p>\n\u003cblockquote>\n\u003cp>My new phone, \u003cstrong>which I bought yesterday\u003c/strong>, is expensive.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>which\u003c/code>를 빼면 안 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ My new phone, I bought yesterday, is expensive.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>비제한적 관계절 = 관계대명사 생략 불가\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. 말할 때도 쉼표가 느껴진다\u003c/h2>\n\u003cp>비제한적 관계절은 말할 때도 약간 끊어서 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>My wife, / who works nearby, / is coming.\u003c/p>\n\u003c/blockquote>\n\u003cp>관계절이 문장 속에 \u003cstrong>삽입된 추가 설명\u003c/strong>처럼 들린다.\u003c/p>\n\u003cp>제한적 관계절은 거의 끊지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>The woman who works nearby is my wife.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>the woman who works nearby\u003c/code>가 한 덩어리다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. 고유명사와 자주 쓰이는 비제한적 관계절\u003c/h2>\n\u003cp>고유명사는 이미 대상을 특정한다.\u003c/p>\n\u003cp>그래서 추가 설명을 붙이면 보통 쉼표를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>Narin, \u003cstrong>who loves swimming\u003c/strong>, is at the pool.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Narin\u003c/code>이라는 이름만으로 이미 누구인지 특정된다.\u003c/p>\n\u003cp>\u003ccode>who loves swimming\u003c/code>은 추가 설명이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. \u003ccode>which\u003c/code>가 문장 전체를 받을 수도 있다\u003c/h2>\n\u003cp>비제한적 관계절의 중요한 용법이다.\u003c/p>\n\u003cblockquote>\n\u003cp>He missed the meeting, \u003cstrong>which made his boss angry\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 회의에 빠졌고, 그것 때문에 상사가 화났다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>which\u003c/code>는 특정 명사 하나가 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그가 회의에 빠진 사실 전체\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 받는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">핵심 정리\u003c/h2>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">제한적 관계절\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>쉼표 없음\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>앞 명사를 \u003cstrong>구별하는 데 필요한 설명\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>The man \u003cstrong>who called me\u003c/strong> is my boss.\u003c/p>\n\u003c/blockquote>\n\u003cp>누구냐?\u003c/p>\n\u003cblockquote>\n\u003cp>나한테 전화한 남자\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">비제한적 관계절\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>쉼표 있음\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 특정된 명사에 \u003cstrong>추가 정보\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>My boss, \u003cstrong>who called me yesterday\u003c/strong>, is on vacation.\u003c/p>\n\u003c/blockquote>\n\u003cp>누구인지는 이미 \u003ccode>my boss\u003c/code>로 특정되어 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">문법 차이\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>구분\u003c/th>\n\u003cth>제한적\u003c/th>\n\u003cth>비제한적\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>쉼표\u003c/td>\n\u003ctd>없음\u003c/td>\n\u003ctd>있음\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>정보\u003c/td>\n\u003ctd>대상 특정\u003c/td>\n\u003ctd>추가 설명\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003ccode>that\u003c/code>\u003c/td>\n\u003ctd>가능\u003c/td>\n\u003ctd>불가\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>목적격 관계대명사 생략\u003c/td>\n\u003ctd>가능\u003c/td>\n\u003ctd>불가\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">연습\u003c/h2>\n\u003cp>뜻에 맞는 문장을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>\u003cstrong>서울에 사는 직원들만\u003c/strong> 재택근무를 한다.\u003c/p>\n\u003cul>\n\u003cli>The employees who live in Seoul work from home.\u003c/li>\n\u003cli>The employees, who live in Seoul, work from home.\u003c/li>\n\u003c/ul>\n\u003c/li>\n\u003cli>\u003cp>내 차는 한 대뿐이고, 그 차는 작년에 샀다.\u003c/p>\n\u003cul>\n\u003cli>My car that I bought last year is new.\u003c/li>\n\u003cli>My car, which I bought last year, is new.\u003c/li>\n\u003c/ul>\n\u003c/li>\n\u003cli>\u003cp>비제한적 관계절에서 가능한 것은?\u003c/p>\n\u003cul>\n\u003cli>my phone, that I bought yesterday\u003c/li>\n\u003cli>my phone, which I bought yesterday\u003c/li>\n\u003c/ul>\n\u003c/li>\n\u003cli>\u003cp>다음 중 관계대명사를 생략할 수 있는 것은?\u003c/p>\n\u003cul>\n\u003cli>The book that I bought was expensive.\u003c/li>\n\u003cli>My book, which I bought yesterday, was expensive.\u003c/li>\n\u003c/ul>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>56단계 — 간접의문문 \u003ccode>Do you know where he is?\u003c/code> : 왜 \u003ccode>where is he\u003c/code>가 아닌가\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 제한적 관계절 — 쉼표 없음","depth":2},{"id":"reading-2","label":"2. 비제한적 관계절 — 쉼표 있음","depth":2},{"id":"reading-3","label":"3. 두 문장을 비교","depth":2},{"id":"reading-4","label":"쉼표 없음","depth":3},{"id":"reading-5","label":"쉼표 있음","depth":3},{"id":"reading-6","label":"4. 핵심은 “정보가 중요한가?”가 아니다","depth":2},{"id":"reading-7","label":"예","depth":2},{"id":"reading-8","label":"5. 비제한적 관계절에서는 that을 쓰지 않는다","depth":2},{"id":"reading-9","label":"제한적","depth":3},{"id":"reading-10","label":"비제한적","depth":3},{"id":"reading-11","label":"6. 비제한적 관계절의 관계대명사는 생략하지 않는다","depth":2},{"id":"reading-12","label":"7. 말할 때도 쉼표가 느껴진다","depth":2},{"id":"reading-13","label":"8. 고유명사와 자주 쓰이는 비제한적 관계절","depth":2},{"id":"reading-14","label":"9. which가 문장 전체를 받을 수도 있다","depth":2},{"id":"reading-15","label":"핵심 정리","depth":2},{"id":"reading-16","label":"제한적 관계절","depth":2},{"id":"reading-17","label":"비제한적 관계절","depth":2},{"id":"reading-18","label":"문법 차이","depth":2},{"id":"reading-19","label":"연습","depth":2}],"origin":"conversation","characters":3633,"aliases":{"structure":"concept","examples":"reading-7","contrast":"reading-3","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-16"}},{"id":56,"title":"56단계 — 간접의문문 Do you know where he is?","html":"\u003ch1 id=\"lesson-title\" data-id=\"56\">56단계 — 간접의문문 \u003ccode>Do you know where he is?\u003c/code>\u003c/h1>\n\u003cp>이번에는 직접 질문을 문장 안에 넣는 \u003cstrong>간접의문문\u003c/strong>을 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>간접의문문 안에서는 평서문 어순을 쓴다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Do you know \u003cstrong>where is he\u003c/strong>?\u003cbr>✅ Do you know \u003cstrong>where he is\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 직접의문문\u003c/h2>\n\u003cp>그냥 직접 묻는 질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Where is he?\u003c/strong>\u003cbr>그는 어디 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>be동사가 주어 앞으로 나온다.\u003c/p>\n\u003cblockquote>\n\u003cp>Where + is + he?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 간접의문문\u003c/h2>\n\u003cp>앞에 다른 표현이 붙으면:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know \u003cstrong>where he is\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>그가 어디 있는지 알아?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>where he is\u003c/code>는 더 이상 독립적인 질문이 아니라, \u003ccode>know\u003c/code>의 내용이 된다.\u003c/p>\n\u003cp>그래서 질문 어순:\u003c/p>\n\u003cblockquote>\n\u003cp>where \u003cstrong>is he\u003c/strong> ❌\u003c/p>\n\u003c/blockquote>\n\u003cp>가 아니라 평서문 어순:\u003c/p>\n\u003cblockquote>\n\u003cp>where \u003cstrong>he is\u003c/strong> ✅\u003c/p>\n\u003c/blockquote>\n\u003cp>를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>의문사 + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>where \u003cstrong>he is\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>what \u003cstrong>she wants\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>when \u003cstrong>they will arrive\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>why \u003cstrong>he left\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>how \u003cstrong>this works\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>what\u003c/code> 예문\u003c/h2>\n\u003cp>직접 질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>What does she want?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>간접 질문:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know \u003cstrong>what she wants\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>중요한 변화가 두 개 있다.\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">직접의문문\u003c/h3>\n\u003cblockquote>\n\u003cp>What \u003cstrong>does she want\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">간접의문문\u003c/h3>\n\u003cblockquote>\n\u003cp>what \u003cstrong>she wants\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>does\u003c/code>가 사라지고:\u003c/p>\n\u003cblockquote>\n\u003cp>want → wants\u003c/p>\n\u003c/blockquote>\n\u003cp>가 된다.\u003c/p>\n\u003cp>왜냐하면 내부 문장이 다시 평서문 구조가 되었기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>where does he live?\u003c/code>\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>Where \u003cstrong>does he live\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know \u003cstrong>where he lives\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Do you know where does he live?\u003cbr>✅ Do you know where he lives?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 과거도 같은 원리\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>When \u003cstrong>did she leave\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know \u003cstrong>when she left\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>did\u003c/code>가 사라지고:\u003c/p>\n\u003cblockquote>\n\u003cp>leave → left\u003c/p>\n\u003c/blockquote>\n\u003cp>로 돌아간다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 왜 \u003ccode>do / does / did\u003c/code>가 사라지나?\u003c/h2>\n\u003cp>\u003ccode>do / does / did\u003c/code>는 일반동사 \u003cstrong>의문문을 만들기 위해\u003c/strong> 사용한다.\u003c/p>\n\u003cp>하지만 간접의문문 내부는 질문 어순을 사용하지 않는다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>What does he want?\u003c/p>\n\u003c/blockquote>\n\u003cp>가 문장 안으로 들어가면:\u003c/p>\n\u003cblockquote>\n\u003cp>what he wants\u003c/p>\n\u003c/blockquote>\n\u003cp>가 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. be동사도 똑같다\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>Why \u003cstrong>is she\u003c/strong> angry?\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know why \u003cstrong>she is\u003c/strong> angry?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ why is she angry\u003cbr>✅ why she is angry\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 조동사가 있는 경우\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>When \u003cstrong>can he come\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know when \u003cstrong>he can come\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>직접 질문에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>can + he\u003c/p>\n\u003c/blockquote>\n\u003cp>간접에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>he + can\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">10. \u003ccode>will\u003c/code>도 마찬가지\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>When \u003cstrong>will they arrive\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know when \u003cstrong>they will arrive\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">11. 자주 쓰는 시작 표현\u003c/h2>\n\u003cp>간접의문문은 이런 표현 뒤에 자주 온다.\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know ...?\u003cbr>~인지 알아?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Can you tell me ...?\u003cbr>~인지 알려줄래?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I don&#39;t know ...\u003cbr>~인지 모르겠다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m not sure ...\u003cbr>~인지 확실하지 않다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wonder ...\u003cbr>~인지 궁금하다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">예문\u003c/h2>\n\u003cblockquote>\n\u003cp>Can you tell me \u003cstrong>where the bathroom is\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>화장실이 어디인지 알려주시겠어요?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I don&#39;t know \u003cstrong>what he wants\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그가 무엇을 원하는지 모르겠다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I wonder \u003cstrong>why she left\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 왜 떠났는지 궁금하다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">12. 의문사가 없는 질문은 \u003ccode>if / whether\u003c/code>\u003c/h2>\n\u003cp>직접 질문:\u003c/p>\n\u003cblockquote>\n\u003cp>Is he busy?\u003c/p>\n\u003c/blockquote>\n\u003cp>이건 \u003ccode>who / what / where\u003c/code> 같은 의문사가 없다.\u003c/p>\n\u003cp>간접으로 바꾸면:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know \u003cstrong>if he is busy\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>그가 바쁜지 알아?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>if\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~인지 아닌지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">13. \u003ccode>whether\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>whether\u003c/code>도 같은 역할을 한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I don&#39;t know \u003cstrong>whether he is coming\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 오는지 아닌지 모르겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>if / whether = ~인지 아닌지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">14. 비교\u003c/h2>\n\u003cp>직접:\u003c/p>\n\u003cblockquote>\n\u003cp>Does she like coffee?\u003c/p>\n\u003c/blockquote>\n\u003cp>간접:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know \u003cstrong>if she likes coffee\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Do you know if does she like coffee?\u003cbr>✅ Do you know if she likes coffee?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">15. 아주 중요한 예외 — 의문사가 주어인 경우\u003c/h2>\n\u003cp>앞에서 배웠던 것과 연결된다.\u003c/p>\n\u003cp>직접 질문:\u003c/p>\n\u003cblockquote>\n\u003cp>Who called you?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>who\u003c/code>가 이미 주어다.\u003c/p>\n\u003cp>이 문장은 원래도:\u003c/p>\n\u003cblockquote>\n\u003cp>who + called\u003c/p>\n\u003c/blockquote>\n\u003cp>평서문과 같은 어순이다.\u003c/p>\n\u003cp>간접으로 넣어도:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you know \u003cstrong>who called you\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>형태가 그대로다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">핵심\u003c/h2>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">직접의문문\u003c/h2>\n\u003cblockquote>\n\u003cp>Where \u003cstrong>is he\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>What \u003cstrong>does she want\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>When \u003cstrong>did he leave\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">간접의문문\u003c/h2>\n\u003cblockquote>\n\u003cp>Do you know where \u003cstrong>he is\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Do you know what \u003cstrong>she wants\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Do you know when \u003cstrong>he left\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>간접의문문 = 의문사 + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>Do you know \u003cstrong>where he is / where is he\u003c/strong>?\u003c/li>\n\u003cli>Can you tell me \u003cstrong>what she wants / what does she want\u003c/strong>?\u003c/li>\n\u003cli>I don&#39;t know \u003cstrong>when he left / when did he leave\u003c/strong>.\u003c/li>\n\u003cli>Do you know \u003cstrong>why she is angry / why is she angry\u003c/strong>?\u003c/li>\n\u003cli>Do you know \u003cstrong>if he likes coffee / if does he like coffee\u003c/strong>?\u003c/li>\n\u003cli>I wonder \u003cstrong>where they are / where are they\u003c/strong>.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>57단계 — 명사절 \u003ccode>what I want / that he is busy\u003c/code>: 문장 전체를 명사처럼 쓰는 구조\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 직접의문문","depth":2},{"id":"reading-2","label":"2. 간접의문문","depth":2},{"id":"reading-3","label":"3. 기본 구조","depth":2},{"id":"reading-4","label":"4. what 예문","depth":2},{"id":"reading-5","label":"직접의문문","depth":3},{"id":"reading-6","label":"간접의문문","depth":3},{"id":"reading-7","label":"5. where does he live?","depth":2},{"id":"reading-8","label":"6. 과거도 같은 원리","depth":2},{"id":"reading-9","label":"7. 왜 do / does / did가 사라지나?","depth":2},{"id":"reading-10","label":"8. be동사도 똑같다","depth":2},{"id":"reading-11","label":"9. 조동사가 있는 경우","depth":2},{"id":"reading-12","label":"10. will도 마찬가지","depth":2},{"id":"reading-13","label":"11. 자주 쓰는 시작 표현","depth":2},{"id":"reading-14","label":"예문","depth":2},{"id":"reading-15","label":"12. 의문사가 없는 질문은 if / whether","depth":2},{"id":"reading-16","label":"13. whether","depth":2},{"id":"reading-17","label":"14. 비교","depth":2},{"id":"reading-18","label":"15. 아주 중요한 예외 — 의문사가 주어인 경우","depth":2},{"id":"reading-19","label":"핵심","depth":2},{"id":"reading-20","label":"직접의문문","depth":2},{"id":"reading-21","label":"간접의문문","depth":2},{"id":"reading-22","label":"연습","depth":2}],"origin":"conversation","characters":3591,"aliases":{"structure":"reading-3","examples":"reading-4","contrast":"reading-17","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"reading-14"}},{"id":57,"title":"57단계 — 명사절 what I want / that he is busy","html":"\u003ch1 id=\"lesson-title\" data-id=\"57\">57단계 — 명사절 \u003ccode>what I want / that he is busy\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>문장 전체가 명사처럼 작동하는 구조\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사로 된 작은 문장을 하나의 명사 덩어리처럼 사용한다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>that he is busy\u003c/strong>.\u003cbr>나는 \u003cstrong>그가 바쁘다는 것을\u003c/strong> 안다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>that he is busy\u003c/code> 전체가 \u003ccode>know\u003c/code>의 목적어다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 먼저 일반 명사와 비교\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">명사 하나\u003c/h3>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>the answer\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>know = 동사\u003c/li>\n\u003cli>the answer = 목적어\u003c/li>\n\u003c/ul>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">문장 덩어리\u003c/h3>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>that he is busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 \u003ccode>the answer\u003c/code> 대신:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>that he is busy\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 문장 덩어리가 목적어 자리에 들어갔다.\u003c/p>\n\u003cp>그래서 이것을 \u003cstrong>명사절\u003c/strong>이라고 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. \u003ccode>that + 주어 + 동사\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>that\u003c/code> 명사절은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~라는 것 / ~라고\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미를 만든다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I think \u003cstrong>that she is right\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그녀가 맞다고 생각한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>that he works here\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그가 여기서 일한다는 것을 안다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She said \u003cstrong>that she was tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 피곤하다고 말했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>I think \u003cstrong>that she is right\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>분석:\u003c/p>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>think = 동사\u003c/li>\n\u003cli>that she is right = 목적어\u003c/li>\n\u003c/ul>\n\u003cp>그리고 명사절 안에서는:\u003c/p>\n\u003cul>\n\u003cli>she = 주어\u003c/li>\n\u003cli>is = 동사\u003c/li>\n\u003cli>right = 형용사\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>[I] [think] [that she is right].\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 큰 문장 안에 작은 문장이 들어 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>that\u003c/code>은 자주 생략된다\u003c/h2>\n\u003cp>회화에서는 목적어 역할의 \u003ccode>that\u003c/code>을 자주 뺀다.\u003c/p>\n\u003cblockquote>\n\u003cp>I think \u003cstrong>that she is right\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>=\u003c/p>\n\u003cblockquote>\n\u003cp>I think \u003cstrong>she is right\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 맞다.\u003c/p>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>that you are busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>you are busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>회화에서는 두 번째가 아주 자연스럽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>what + 주어 + 동사\u003c/code>\u003c/h2>\n\u003cp>이번에는 \u003ccode>what\u003c/code>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>what you want\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 \u003cstrong>네가 원하는 것이 무엇인지 / 네가 원하는 것을\u003c/strong> 안다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>what you want\u003c/p>\n\u003c/blockquote>\n\u003cp>전체가 \u003ccode>know\u003c/code>의 목적어다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>what\u003c/code> 자체가 “것”을 포함한다\u003c/h2>\n\u003cp>이게 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>what = \u003cstrong>the thing that\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 이해할 수 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>what you made\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 \u003cstrong>네가 만든 것을\u003c/strong> 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>what you made\u003cbr>= the thing that you made\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 \u003ccode>what\u003c/code> 자체에 이미 \u003cstrong>“것”\u003c/strong>이라는 의미가 포함되어 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>that\u003c/code>과 \u003ccode>what\u003c/code>의 차이\u003c/h2>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">\u003ccode>that\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>that he is busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>that\u003c/code> 자체에는 “것”이라는 구체적인 뜻이 거의 없다.\u003c/p>\n\u003cp>그냥:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그가 바쁘다는 사실\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>전체를 연결한다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">\u003ccode>what\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>what he wants\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>what\u003c/code> 자체가:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그가 원하는 것\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 의미를 가진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. 그래서 이런 차이가 난다\u003c/h2>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>that he wants a car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그가 차를 원한다는 것을 안다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>that\u003c/code> 뒤 문장은 완전하다.\u003c/p>\n\u003cblockquote>\n\u003cp>he wants a car\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>he = 주어\u003c/li>\n\u003cli>wants = 동사\u003c/li>\n\u003cli>a car = 목적어\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>what he wants\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그가 무엇을 원하는지 안다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>what\u003c/code>이 \u003ccode>wants\u003c/code>의 목적어 역할을 한다.\u003c/p>\n\u003cp>원래:\u003c/p>\n\u003cblockquote>\n\u003cp>He wants \u003cstrong>something\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>그 \u003ccode>something\u003c/code> 자리를 \u003ccode>what\u003c/code>이 차지한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. \u003ccode>what\u003c/code> 뒤에는 목적어를 또 쓰면 안 된다\u003c/h2>\n\u003cblockquote>\n\u003cp>✅ I know what he wants.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I know what he wants it.\u003c/p>\n\u003c/blockquote>\n\u003cp>왜냐하면 \u003ccode>what\u003c/code> 자체가 이미 \u003ccode>wants\u003c/code>의 목적어이기 때문이다.\u003c/p>\n\u003cp>같은 원리:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I know what she bought.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I know what she bought it.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">10. \u003ccode>who / where / when / why / how\u003c/code>도 명사절을 만든다\u003c/h2>\n\u003cp>앞 단계의 간접의문문과 연결된다.\u003c/p>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>who he is\u003c/strong>.\u003cbr>나는 그가 누구인지 안다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>where she lives\u003c/strong>.\u003cbr>나는 그녀가 어디 사는지 안다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I remember \u003cstrong>when we met\u003c/strong>.\u003cbr>나는 우리가 언제 만났는지 기억한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I understand \u003cstrong>why he left\u003c/strong>.\u003cbr>나는 그가 왜 떠났는지 이해한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Show me \u003cstrong>how this works\u003c/strong>.\u003cbr>이게 어떻게 작동하는지 보여줘.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 덩어리들이 전부 명사 역할을 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">11. 명사절은 주어도 될 수 있다\u003c/h2>\n\u003cp>목적어뿐 아니라 문장의 주어로도 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>What you said\u003c/strong> is true.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네가 말한 것은 사실이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>What you said\u003c/p>\n\u003c/blockquote>\n\u003cp>전체가 주어다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>[What you said] / is / true.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>What I need\u003c/strong> is time.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 필요한 것은 시간이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>What I need = 내가 필요한 것\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">12. \u003ccode>that\u003c/code>절도 주어가 될 수 있다\u003c/h2>\n\u003cp>문법적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>That he failed the test\u003c/strong> surprised me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 시험에 떨어졌다는 사실이 나를 놀라게 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 회화에서는 이런 긴 명사절을 문장 맨 앞에 두는 것보다:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It surprised me that he failed the test.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003ccode>it\u003c/code>을 앞에 두는 경우가 많다.\u003c/p>\n\u003cp>이 구조는 나중에 \u003ccode>가주어 it\u003c/code>에서 자세히 다룬다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">13. 관계대명사 \u003ccode>what\u003c/code>은 아니다\u003c/h2>\n\u003cp>여기서 헷갈릴 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>what I want\u003c/p>\n\u003c/blockquote>\n\u003cp>에서 \u003ccode>what\u003c/code>은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>내가 원하는 것\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 뜻을 만든다.\u003c/p>\n\u003cp>앞에 꾸며줄 명사가 없다.\u003c/p>\n\u003cp>반면 관계대명사:\u003c/p>\n\u003cblockquote>\n\u003cp>the book \u003cstrong>that I want\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 앞에 이미:\u003c/p>\n\u003cblockquote>\n\u003cp>the book\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 명사가 있다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ the book what I want\u003c/p>\n\u003c/blockquote>\n\u003cp>표준 영어에서는 쓰지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">핵심\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">\u003ccode>that + 완전한 문장\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>that he is busy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 바쁘다는 것을 안다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">\u003ccode>what + 불완전한 문장\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>what he wants\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 원하는 것을 안다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>what\u003c/code>이 이미 문장 안에서 한 자리를 담당한다.\u003c/p>\n\u003cp>그리고 명사절은 전체가:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 / 목적어\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 명사 역할을 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I know \u003cstrong>that he is busy / what he is busy\u003c/strong>.\u003c/li>\n\u003cli>I know \u003cstrong>what she wants / what she wants it\u003c/strong>.\u003c/li>\n\u003cli>\u003cstrong>What you said / That you said it\u003c/strong> is true.\u003cbr>→ 네가 말한 내용은 사실이다.\u003c/li>\n\u003cli>I think \u003cstrong>that she is right / what she is right\u003c/strong>.\u003c/li>\n\u003cli>I know \u003cstrong>where he lives / where does he live\u003c/strong>.\u003c/li>\n\u003cli>The book \u003cstrong>that I bought / what I bought\u003c/strong> was expensive.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>58단계 — 가주어 \u003ccode>it\u003c/code>: \u003ccode>It is important to study\u003c/code>가 왜 필요한가\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 먼저 일반 명사와 비교","depth":2},{"id":"reading-2","label":"명사 하나","depth":3},{"id":"reading-3","label":"문장 덩어리","depth":3},{"id":"reading-4","label":"2. that + 주어 + 동사","depth":2},{"id":"reading-5","label":"3. 구조","depth":2},{"id":"reading-6","label":"4. that은 자주 생략된다","depth":2},{"id":"reading-7","label":"5. what + 주어 + 동사","depth":2},{"id":"reading-8","label":"6. what 자체가 “것”을 포함한다","depth":2},{"id":"reading-9","label":"7. that과 what의 차이","depth":2},{"id":"reading-10","label":"that","depth":3},{"id":"reading-11","label":"what","depth":3},{"id":"reading-12","label":"8. 그래서 이런 차이가 난다","depth":2},{"id":"reading-13","label":"9. what 뒤에는 목적어를 또 쓰면 안 된다","depth":2},{"id":"reading-14","label":"10. who / where / when / why / how도 명사절을 만든다","depth":2},{"id":"reading-15","label":"11. 명사절은 주어도 될 수 있다","depth":2},{"id":"reading-16","label":"12. that절도 주어가 될 수 있다","depth":2},{"id":"reading-17","label":"13. 관계대명사 what은 아니다","depth":2},{"id":"reading-18","label":"핵심","depth":2},{"id":"reading-19","label":"that + 완전한 문장","depth":3},{"id":"reading-20","label":"what + 불완전한 문장","depth":3},{"id":"reading-21","label":"연습","depth":2}],"origin":"conversation","characters":4087,"aliases":{"structure":"reading-5","examples":"concept","contrast":"reading-1","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-16"}},{"id":58,"title":"58단계 — 가주어 it","html":"\u003ch1 id=\"lesson-title\" data-id=\"58\">58단계 — 가주어 \u003ccode>it\u003c/code>\u003c/h1>\n\u003cp>이번에는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It is important to study.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 문장에서 \u003cstrong>왜 \u003ccode>it\u003c/code>이 필요한지\u003c/strong> 배운다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>영어는 \u003cstrong>긴 주어를 뒤로 보내고\u003c/strong>, 앞자리에 \u003ccode>it\u003c/code>을 세우는 것을 매우 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 원래 구조\u003c/h2>\n\u003cp>문법적으로는 이렇게 말할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>To study English is important.\u003c/strong>\u003cbr>영어를 공부하는 것은 중요하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cul>\n\u003cli>To study English = 주어\u003c/li>\n\u003cli>is = 동사\u003c/li>\n\u003cli>important = 형용사\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>[To study English] + is + important.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로 맞다.\u003c/p>\n\u003cp>하지만 영어에서는 긴 주어가 앞에 오는 것을 다소 무겁게 느낀다.\u003c/p>\n\u003cp>그래서 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It is important to study English.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 여기서 \u003ccode>it\u003c/code>은 무엇을 가리키나?\u003c/h2>\n\u003cp>보통의 \u003ccode>it\u003c/code>처럼 특정 사물을 가리키지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>It is expensive.\u003cbr>그것은 비싸다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>it\u003c/code> = 어떤 물건.\u003c/p>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It is important to study English.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기의 \u003ccode>it\u003c/code>은 특별한 의미가 없다.\u003c/p>\n\u003cp>진짜 내용은 뒤의:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to study English\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003cp>그래서 \u003ccode>it\u003c/code>을 \u003cstrong>가주어\u003c/strong>, \u003ccode>to study English\u003c/code>를 \u003cstrong>진주어\u003c/strong>라고 부른다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 문장 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>It + be동사 + 형용사 + to부정사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>It is \u003cstrong>easy to understand\u003c/strong>.\u003cbr>이해하기 쉽다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It is \u003cstrong>hard to explain\u003c/strong>.\u003cbr>설명하기 어렵다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It is \u003cstrong>important to practice\u003c/strong>.\u003cbr>연습하는 것이 중요하다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">구조 분석\u003c/h2>\n\u003cblockquote>\n\u003cp>It is difficult to learn English.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>It = 가주어\u003c/li>\n\u003cli>is = be동사\u003c/li>\n\u003cli>difficult = 형용사\u003c/li>\n\u003cli>to learn English = 진짜 내용\u003c/li>\n\u003c/ul>\n\u003cp>의미상으로는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>영어를 배우는 것\u003c/strong>이 어렵다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. 왜 그냥 \u003ccode>To learn English is difficult\u003c/code>라고 안 하나?\u003c/h2>\n\u003cp>가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>To learn English is difficult.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 일상적인 영어에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It is difficult to learn English.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 훨씬 자연스럽다.\u003c/p>\n\u003cp>영어는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>짧은 요소를 먼저, 긴 정보를 뒤에\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>두려는 성향이 강하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">5. 자주 쓰는 형용사\u003c/h2>\n\u003cp>이 구조와 아주 잘 어울린다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>표현\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>It is easy to...\u003c/td>\n\u003ctd>~하기 쉽다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>It is hard to...\u003c/td>\n\u003ctd>~하기 어렵다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>It is difficult to...\u003c/td>\n\u003ctd>~하기 어렵다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>It is important to...\u003c/td>\n\u003ctd>~하는 것이 중요하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>It is necessary to...\u003c/td>\n\u003ctd>~할 필요가 있다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>It is possible to...\u003c/td>\n\u003ctd>~하는 것이 가능하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>It is impossible to...\u003c/td>\n\u003ctd>~하는 것이 불가능하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>It is good to...\u003c/td>\n\u003ctd>~하는 것이 좋다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">6. 예문\u003c/h2>\n\u003cblockquote>\n\u003cp>It is easy \u003cstrong>to use this app\u003c/strong>.\u003cbr>이 앱을 사용하는 것은 쉽다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It is difficult \u003cstrong>to understand him\u003c/strong>.\u003cbr>그를 이해하기 어렵다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It is important \u003cstrong>to get enough sleep\u003c/strong>.\u003cbr>충분히 자는 것이 중요하다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">7. 사람을 넣고 싶으면 \u003ccode>for + 사람\u003c/code>\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>It is difficult \u003cstrong>for me to understand this\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 이것을 이해하기는 어렵다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It + be + 형용사 + for + 사람 + to부정사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>for me = 나에게는 / 내가\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>to understand\u003c/code>의 행동 주체가 \u003ccode>me\u003c/code>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>It is easy \u003cstrong>to use this program\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>누가 쓰는지는 중요하지 않다.\u003c/p>\n\u003cblockquote>\n\u003cp>It is easy \u003cstrong>for me to use this program\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>내가\u003c/strong> 이 프로그램을 사용하는 것은 쉽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 왜 \u003ccode>for me\u003c/code>이지 \u003ccode>for I\u003c/code>가 아닌가?\u003c/h2>\n\u003cp>\u003ccode>for\u003c/code>는 전치사다.\u003c/p>\n\u003cp>전치사 뒤에는 목적격을 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>for me\u003cbr>for him\u003cbr>for her\u003cbr>for us\u003cbr>for them\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ for I to understand\u003cbr>✅ for me to understand\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. \u003ccode>of + 사람\u003c/code>을 쓰는 경우도 있다\u003c/h2>\n\u003cp>특정한 사람의 \u003cstrong>성격이나 행동을 평가\u003c/strong>할 때는 \u003ccode>of\u003c/code>를 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>It was kind \u003cstrong>of you to help me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나를 도와주다니 친절하네.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>당신이 친절하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 사람의 성격을 평가한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">비교\u003c/h2>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">\u003ccode>for\u003c/code>\u003c/h3>\n\u003cp>행동의 난이도·필요성 등을 말함.\u003c/p>\n\u003cblockquote>\n\u003cp>It is difficult \u003cstrong>for me to do this\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내가 이것을 하기는 어렵다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">\u003ccode>of\u003c/code>\u003c/h3>\n\u003cp>그 행동을 한 \u003cstrong>사람 자체를 평가\u003c/strong>함.\u003c/p>\n\u003cblockquote>\n\u003cp>It was kind \u003cstrong>of you to help me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네가 도와주다니 친절했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. 자주 나오는 \u003ccode>of + 사람\u003c/code>\u003c/h2>\n\u003cp>대표적인 형용사:\u003c/p>\n\u003cblockquote>\n\u003cp>kind\u003cbr>nice\u003cbr>smart\u003cbr>stupid\u003cbr>rude\u003cbr>careless\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>It was nice \u003cstrong>of you to call me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>전화해주다니 친절하네.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It was careless \u003cstrong>of him to lose the key\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>열쇠를 잃어버리다니 그가 부주의했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">11. \u003ccode>that절\u003c/code>도 뒤로 보낼 수 있다\u003c/h2>\n\u003cp>앞 단계의 명사절과 연결된다.\u003c/p>\n\u003cp>원래:\u003c/p>\n\u003cblockquote>\n\u003cp>That he passed the exam is surprising.\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로 가능하지만 무겁다.\u003c/p>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It is surprising that he passed the exam.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 시험에 합격했다는 것이 놀랍다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It + be + 형용사 + that절\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">12. \u003ccode>to부정사\u003c/code>와 \u003ccode>that절\u003c/code> 비교\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">행동\u003c/h3>\n\u003cblockquote>\n\u003cp>It is important \u003cstrong>to study\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>공부하는 것이 중요하다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">사실\u003c/h3>\n\u003cblockquote>\n\u003cp>It is important \u003cstrong>that you study every day\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네가 매일 공부하는 것이 중요하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>that절\u003c/code>은 주어와 동사를 명확하게 넣을 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">핵심\u003c/h2>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">기본 구조\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>It is + 형용사 + to부정사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It is important to study.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>it\u003c/code> = 가주어\u003cbr>\u003ccode>to study\u003c/code> = 실제 내용\u003c/p>\n\u003c/blockquote>\n\u003cp>사람을 넣으면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It is + 형용사 + for + 사람 + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It is hard for me to understand.\u003c/p>\n\u003c/blockquote>\n\u003cp>사람 자체를 평가하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>It is + 형용사 + of + 사람 + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It was kind of you to help me.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>It is important to study / To study it is important\u003c/strong> English.\u003c/li>\n\u003cli>It is difficult \u003cstrong>for me / for I\u003c/strong> to understand this.\u003c/li>\n\u003cli>It was kind \u003cstrong>of you / for you\u003c/strong> to help me.\u003c/li>\n\u003cli>It is easy \u003cstrong>to use / using\u003c/strong> this program.\u003c/li>\n\u003cli>It is surprising \u003cstrong>that he passed / what he passed\u003c/strong> the exam.\u003c/li>\n\u003cli>\u003ccode>It is hard for me to do this.\u003c/code>에서 실제 행동의 주체는 \u003cstrong>it / me\u003c/strong>.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>59단계 — \u003ccode>too ... to / enough to\u003c/code>: “너무 ~해서 못한다 / ~할 만큼 충분하다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 원래 구조","depth":2},{"id":"reading-2","label":"2. 여기서 it은 무엇을 가리키나?","depth":2},{"id":"reading-3","label":"3. 문장 구조","depth":2},{"id":"reading-4","label":"구조 분석","depth":2},{"id":"reading-5","label":"4. 왜 그냥 To learn English is difficult라고 안 하나?","depth":2},{"id":"reading-6","label":"5. 자주 쓰는 형용사","depth":2},{"id":"reading-7","label":"6. 예문","depth":2},{"id":"reading-8","label":"7. 사람을 넣고 싶으면 for + 사람","depth":2},{"id":"reading-9","label":"비교","depth":2},{"id":"reading-10","label":"8. 왜 for me이지 for I가 아닌가?","depth":2},{"id":"reading-11","label":"9. of + 사람을 쓰는 경우도 있다","depth":2},{"id":"reading-12","label":"비교","depth":2},{"id":"reading-13","label":"for","depth":3},{"id":"reading-14","label":"of","depth":3},{"id":"reading-15","label":"10. 자주 나오는 of + 사람","depth":2},{"id":"reading-16","label":"11. that절도 뒤로 보낼 수 있다","depth":2},{"id":"reading-17","label":"12. to부정사와 that절 비교","depth":2},{"id":"reading-18","label":"행동","depth":3},{"id":"reading-19","label":"사실","depth":3},{"id":"reading-20","label":"핵심","depth":2},{"id":"reading-21","label":"기본 구조","depth":3},{"id":"reading-22","label":"연습","depth":2}],"origin":"conversation","characters":4149,"aliases":{"structure":"reading-1","examples":"reading-7","contrast":"reading-9","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-11","topic-12":"reading-12"}},{"id":59,"title":"59단계 — too ... to / enough to","html":"\u003ch1 id=\"lesson-title\" data-id=\"59\">59단계 — \u003ccode>too ... to / enough to\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>정도 + 결과\u003c/strong>를 표현하는 두 구조를 배운다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>too + 형용사/부사 + to do\u003c/strong>\u003cbr>너무 ~해서 …할 수 없다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>형용사/부사 + enough + to do\u003c/strong>\u003cbr>…할 만큼 충분히 ~하다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>too ... to\u003c/code>\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>The box is \u003cstrong>too heavy to carry\u003c/strong>.\u003cbr>그 상자는 \u003cstrong>너무 무거워서 들 수 없다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>too + 형용사 + to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>too\u003c/code>는 단순히 \u003cstrong>매우\u003c/strong>가 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>필요한 정도를 지나치게 넘었다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 의미가 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>very\u003c/code>와 \u003ccode>too\u003c/code> 차이\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">very\u003c/h3>\n\u003cblockquote>\n\u003cp>The box is \u003cstrong>very heavy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>상자가 매우 무겁다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그냥 무겁다는 정도만 강하게 말한다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">too\u003c/h3>\n\u003cblockquote>\n\u003cp>The box is \u003cstrong>too heavy to carry\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>들기에는 지나치게 무겁다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>too = 문제가 될 정도로 너무\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 숨겨진 부정 의미\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;m too tired to work.\u003c/p>\n\u003c/blockquote>\n\u003cp>직역하면:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 일하기에 너무 피곤하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제 의미는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>너무 피곤해서 일을 못 하겠다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서 \u003ccode>too ... to\u003c/code> 자체에:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>결과적으로 할 수 없음\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 의미가 들어 있다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I&#39;m too tired not to work.\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 단순히 만드는 게 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 다양한 예\u003c/h2>\n\u003cblockquote>\n\u003cp>It&#39;s \u003cstrong>too cold to swim\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너무 추워서 수영할 수 없다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He is \u003cstrong>too young to drive\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 너무 어려서 운전할 수 없다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This coffee is \u003cstrong>too hot to drink\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 커피는 너무 뜨거워서 마실 수 없다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 행동하는 사람이 다르면 \u003ccode>for + 사람\u003c/code>\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This box is too heavy \u003cstrong>for me to carry\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 상자는 \u003cstrong>내가 들기에는\u003c/strong> 너무 무겁다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>too + 형용사 + for + 사람 + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>for\u003c/code> 뒤에는 목적격:\u003c/p>\n\u003cblockquote>\n\u003cp>for me\u003cbr>for him\u003cbr>for her\u003cbr>for us\u003cbr>for them\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>enough\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>enough\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>충분한 / 충분히\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>old enough to drive\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 운전할 만큼 충분히 나이가 들었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>형용사 + enough + to부정사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 형용사 뒤에 \u003ccode>enough\u003c/code>\u003c/h2>\n\u003cp>이 위치가 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>tall \u003cstrong>enough\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>strong \u003cstrong>enough\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>old \u003cstrong>enough\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>good \u003cstrong>enough\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ enough tall\u003cbr>✅ tall enough\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>tall enough to reach\u003c/strong> the shelf.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 선반에 닿을 만큼 키가 크다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 그런데 명사에서는 \u003ccode>enough\u003c/code>가 앞에 온다\u003c/h2>\n\u003cp>형용사와 위치가 다르다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">형용사\u003c/h3>\n\u003cblockquote>\n\u003cp>old \u003cstrong>enough\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">명사\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>enough money\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>enough money to buy\u003c/strong> it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 그것을 살 만큼 충분한 돈이 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>strong \u003cstrong>enough\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>enough strength\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>형용사 + enough\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>enough + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 순서를 기억해야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. \u003ccode>enough to + 동사원형\u003c/code>\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I have enough time \u003cstrong>to finish\u003c/strong> this.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이것을 끝낼 충분한 시간이 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is strong enough \u003cstrong>to lift\u003c/strong> it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 그것을 들 만큼 충분히 힘이 세다.\u003c/p>\n\u003c/blockquote>\n\u003cp>항상:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>to + 동사원형\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. \u003ccode>too\u003c/code>와 \u003ccode>enough\u003c/code> 비교\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">too\u003c/h3>\n\u003cblockquote>\n\u003cp>He is \u003cstrong>too young to drive\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너무 어려서 운전할 수 없다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">enough\u003c/h3>\n\u003cblockquote>\n\u003cp>He is \u003cstrong>old enough to drive\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>운전할 만큼 충분히 나이가 들었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>의미가 거의 반대 방향이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">11. 부정형 \u003ccode>not ... enough\u003c/code>\u003c/h2>\n\u003cp>아주 많이 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>not strong enough to lift\u003c/strong> this.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 이것을 들 만큼 힘이 세지 않다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>not + 형용사 + enough + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">\u003ccode>too\u003c/code>와 바꿔 말할 수도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>The box is \u003cstrong>too heavy for me to lift\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>≈\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>not strong enough to lift\u003c/strong> the box.\u003c/p>\n\u003c/blockquote>\n\u003cp>표현하는 관점은 다르지만 결과는 비슷하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">12. \u003ccode>enough\u003c/code> 뒤에 \u003ccode>for + 사람\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>The room is big enough \u003cstrong>for us to use\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그 방은 우리가 사용하기에 충분히 크다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>형용사 + enough + for + 사람 + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">13. 이전에 헷갈렸던 \u003ccode>enough now to\u003c/code>\u003c/h2>\n\u003cp>예를 들어:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m strong enough now to lift it.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조를 나누면:\u003c/p>\n\u003cblockquote>\n\u003cp>I am / strong enough / now / to lift it.\u003c/p>\n\u003c/blockquote>\n\u003cp>핵심 덩어리는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>strong enough to lift it\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>= 그것을 들 만큼 충분히 힘이 세다\u003c/p>\n\u003cp>\u003ccode>now\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금은\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 시간 부사로 중간에 들어간 것이다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>strong \u003cstrong>enough to lift\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 기본 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">핵심\u003c/h2>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">너무 ~해서 할 수 없다\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>too + 형용사 + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It&#39;s too hot to eat.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">~할 만큼 충분히 ~하다\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>형용사 + enough + to do\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It&#39;s cool enough to eat.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">충분한 명사\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>enough + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>enough money\u003cbr>enough time\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>This coffee is \u003cstrong>too hot to drink / too hot drinking\u003c/strong>.\u003c/li>\n\u003cli>She is \u003cstrong>tall enough / enough tall\u003c/strong> to reach it.\u003c/li>\n\u003cli>I don&#39;t have \u003cstrong>money enough / enough money\u003c/strong> to buy it.\u003c/li>\n\u003cli>He is \u003cstrong>too young to drive / too young driving\u003c/strong>.\u003c/li>\n\u003cli>I&#39;m \u003cstrong>not strong enough / not enough strong\u003c/strong> to lift this.\u003c/li>\n\u003cli>This box is too heavy \u003cstrong>for me to carry / for I to carry\u003c/strong>.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>60단계 — \u003ccode>so ... that / such ... that\u003c/code>: “너무 ~해서 결국 …하다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. too ... to","depth":2},{"id":"reading-2","label":"2. very와 too 차이","depth":2},{"id":"reading-3","label":"very","depth":3},{"id":"reading-4","label":"too","depth":3},{"id":"reading-5","label":"3. 숨겨진 부정 의미","depth":2},{"id":"reading-6","label":"4. 다양한 예","depth":2},{"id":"reading-7","label":"5. 행동하는 사람이 다르면 for + 사람","depth":2},{"id":"reading-8","label":"6. enough","depth":2},{"id":"reading-9","label":"7. 형용사 뒤에 enough","depth":2},{"id":"reading-10","label":"8. 그런데 명사에서는 enough가 앞에 온다","depth":2},{"id":"reading-11","label":"형용사","depth":3},{"id":"reading-12","label":"명사","depth":3},{"id":"reading-13","label":"비교","depth":2},{"id":"reading-14","label":"9. enough to + 동사원형","depth":2},{"id":"reading-15","label":"10. too와 enough 비교","depth":2},{"id":"reading-16","label":"too","depth":3},{"id":"reading-17","label":"enough","depth":3},{"id":"reading-18","label":"11. 부정형 not ... enough","depth":2},{"id":"reading-19","label":"too와 바꿔 말할 수도 있다","depth":2},{"id":"reading-20","label":"12. enough 뒤에 for + 사람","depth":2},{"id":"reading-21","label":"13. 이전에 헷갈렸던 enough now to","depth":2},{"id":"reading-22","label":"핵심","depth":2},{"id":"reading-23","label":"너무 ~해서 할 수 없다","depth":3},{"id":"reading-24","label":"~할 만큼 충분히 ~하다","depth":3},{"id":"reading-25","label":"충분한 명사","depth":3},{"id":"reading-26","label":"연습","depth":2}],"origin":"conversation","characters":3664,"aliases":{"structure":"concept","examples":"reading-6","contrast":"reading-2","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-18"}},{"id":60,"title":"60단계 — so ... that / such ... that","html":"\u003ch1 id=\"lesson-title\" data-id=\"60\">60단계 — \u003ccode>so ... that / such ... that\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>정도가 너무 커서 어떤 결과가 생겼다\u003c/strong>는 구조를 배운다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>so + 형용사/부사 + that + 문장\u003c/strong>\u003cbr>너무 ~해서 …하다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>such + 명사구 + that + 문장\u003c/strong>\u003cbr>너무 ~한 명사라서 …하다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>so ... that\u003c/code>\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I was \u003cstrong>so tired that I fell asleep\u003c/strong>.\u003cbr>나는 너무 피곤해서 잠들었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>so + 형용사 + that + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cul>\n\u003cli>so tired = 너무 피곤한\u003c/li>\n\u003cli>that I fell asleep = 그래서 내가 잠들었다는 결과\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>so\u003c/code> 뒤에는 형용사나 부사\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">형용사\u003c/h3>\n\u003cblockquote>\n\u003cp>The movie was \u003cstrong>so boring that I left early\u003c/strong>.\u003cbr>영화가 너무 지루해서 일찍 나왔다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">부사\u003c/h3>\n\u003cblockquote>\n\u003cp>He ran \u003cstrong>so fast that I couldn&#39;t catch him\u003c/strong>.\u003cbr>그가 너무 빨리 달려서 나는 따라잡을 수 없었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>so \u003cstrong>tired\u003c/strong>\u003cbr>so \u003cstrong>expensive\u003c/strong>\u003cbr>so \u003cstrong>quickly\u003c/strong>\u003cbr>so \u003cstrong>slowly\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. \u003ccode>such ... that\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>such\u003c/code>는 뒤에 \u003cstrong>명사\u003c/strong>가 온다는 점이 핵심이다.\u003c/p>\n\u003cblockquote>\n\u003cp>It was \u003cstrong>such a good movie that I watched it twice\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너무 좋은 영화라서 두 번 봤다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>such + a/an + 형용사 + 단수명사 + that + 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>so\u003c/code>와 \u003ccode>such\u003c/code> 비교\u003c/h2>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">형용사를 강조\u003c/h3>\n\u003cblockquote>\n\u003cp>The movie was \u003cstrong>so good that\u003c/strong> I watched it twice.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">명사를 포함해서 강조\u003c/h3>\n\u003cblockquote>\n\u003cp>It was \u003cstrong>such a good movie that\u003c/strong> I watched it twice.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은 비슷하지만 구조가 다르다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>so + good\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>such + a good movie\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. 단수 가산명사\u003c/h2>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>such + a/an + 형용사 + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>such a kind person\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 정말 친절한 사람이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>결과까지 붙이면:\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>such a kind person that everyone likes her\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 너무 친절한 사람이라 모두가 그녀를 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. 복수명사\u003c/h2>\n\u003cp>복수에서는 \u003ccode>a/an\u003c/code>이 없다.\u003c/p>\n\u003cblockquote>\n\u003cp>They are \u003cstrong>such good students that the teacher trusts them\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그들은 너무 좋은 학생들이라 선생님이 그들을 신뢰한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>such + 형용사 + 복수명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. 불가산명사도 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>It was \u003cstrong>such bad weather that we stayed home\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>날씨가 너무 안 좋아서 우리는 집에 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>weather\u003c/code>는 불가산명사이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ such a bad weather\u003cbr>✅ such bad weather\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. \u003ccode>so\u003c/code>와 \u003ccode>too\u003c/code>의 차이\u003c/h2>\n\u003cp>이전 단계와 연결하자.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">too\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>too tired to work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너무 피곤해서 일할 수 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>too + 형용사 + to부정사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">so\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>so tired that I can&#39;t work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너무 피곤해서 일을 할 수 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>so + 형용사 + that + 완전한 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>둘은 비슷한 뜻을 만들 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. 비교\u003c/h2>\n\u003cblockquote>\n\u003cp>The box is \u003cstrong>too heavy for me to carry\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>≈\u003c/p>\n\u003cblockquote>\n\u003cp>The box is \u003cstrong>so heavy that I can&#39;t carry it\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>첫 번째:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>to carry\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>I can&#39;t carry it\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 \u003ccode>that\u003c/code> 뒤에는 \u003cstrong>주어 + 동사\u003c/strong>가 있는 완전한 문장이 온다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. \u003ccode>that\u003c/code>이 생략되기도 한다\u003c/h2>\n\u003cp>회화에서는 가끔:\u003c/p>\n\u003cblockquote>\n\u003cp>I was so tired \u003cstrong>I fell asleep\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003ccode>that\u003c/code>을 생략한다.\u003c/p>\n\u003cp>하지만 학습 단계에서는 먼저:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>so ... that\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>형태를 정확히 익히는 게 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">핵심\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">형용사/부사를 강조\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>so + 형용사/부사 + that + 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It was so cold that I stayed home.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">명사를 강조\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>such + 명사구 + that + 문장\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>It was such a cold day that I stayed home.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>so cold\u003c/strong>\u003cbr>너무 추운\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>such a cold day\u003c/strong>\u003cbr>너무 추운 날\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I was \u003cstrong>so tired that / such tired that\u003c/strong> I fell asleep.\u003c/li>\n\u003cli>It was \u003cstrong>so a good movie / such a good movie\u003c/strong> that I watched it twice.\u003c/li>\n\u003cli>He ran \u003cstrong>so fast that / such fast that\u003c/strong> I couldn&#39;t catch him.\u003c/li>\n\u003cli>They are \u003cstrong>such good students / so good students\u003c/strong> that everyone likes them.\u003c/li>\n\u003cli>It was \u003cstrong>such bad weather / such a bad weather\u003c/strong> that we stayed home.\u003c/li>\n\u003cli>The box was \u003cstrong>so heavy that I couldn&#39;t lift it / too heavy that I couldn&#39;t lift it\u003c/strong>.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>61단계 — \u003ccode>as ... as\u003c/code>: “~만큼 …하다” 비교 표현\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. so ... that","depth":2},{"id":"reading-2","label":"2. so 뒤에는 형용사나 부사","depth":2},{"id":"reading-3","label":"형용사","depth":3},{"id":"reading-4","label":"부사","depth":3},{"id":"reading-5","label":"3. such ... that","depth":2},{"id":"reading-6","label":"4. so와 such 비교","depth":2},{"id":"reading-7","label":"형용사를 강조","depth":3},{"id":"reading-8","label":"명사를 포함해서 강조","depth":3},{"id":"reading-9","label":"5. 단수 가산명사","depth":2},{"id":"reading-10","label":"6. 복수명사","depth":2},{"id":"reading-11","label":"7. 불가산명사도 가능","depth":2},{"id":"reading-12","label":"8. so와 too의 차이","depth":2},{"id":"reading-13","label":"too","depth":3},{"id":"reading-14","label":"so","depth":3},{"id":"reading-15","label":"9. 비교","depth":2},{"id":"reading-16","label":"10. that이 생략되기도 한다","depth":2},{"id":"reading-17","label":"핵심","depth":2},{"id":"reading-18","label":"형용사/부사를 강조","depth":3},{"id":"reading-19","label":"명사를 강조","depth":3},{"id":"reading-20","label":"비교","depth":2},{"id":"reading-21","label":"연습","depth":2}],"origin":"conversation","characters":3012,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-6","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-20"}}]);
